/* Katalog položek schvalovacího registru – součást jádra (přesun z demo/ 18. 10. 2026, rozhodnutí vlastníka: produkční sestavení bez demo/ musí mít registr i jídla).
   Stav schválení, datum a kdo rozhodl doplní NF.seedRegistry; průvodce položkou (demo/guide.js) připojí prezentační vrstva.
   scope 'provozni' = provozní položka (formát exportu, texty obrazovek, zaučení, milníky): neschvaluje ji nikdo (rozhodnutí vlastníka 27. 10. 2026): nemá stav ani štítek a v registru je jen jako popis pravidla aplikace.
   Klinické hodnoty a prahy jsou návrh autora makety. Žádná skutečná jména osob, institucí ani výrobců. */
(function (global) {
'use strict';
var NF = global.NutriFee; NF.data = NF.data || {};
NF.data.registry = function () {
  /* Kontrola 4 (bod 1, vlastník 30. 10. 2026): každá položka nese číslo verze (`version`, výchozí „v1“); NF.newVersion ho zvyšuje.
     Otisk znění, parametrů a textu „Co schvalujete“ počítá NF.itemFingerprint (jádro), ukládá ho prezentační vrstva u každého rozhodnutí. */
  var A = function (o) { o.params = o.params || {}; o.version = o.version || 'v1'; return o; };
  var list = [
    A({ id: 'K-KRITERIA', version: 'v2' /* SCHEMA 90: nová verze ke schválení */, cat: 'kohorta', title: 'Podmínky zařazení', summary: 'Zařadit lze dospělého s diabetem 2. typu (DM2), který má inzulin v pevných dávkách (bazál 1× denně večer a tři dávky k jídlu) bez korekčního schématu (žádné dávky navíc podle aktuální glukózy), nosí senzor glukózy (CGM) a nebere žádný jiný lék na diabetes: ani tablety, ani GLP-1. Premixy ne, protože jejich dávku nelze přiřadit k jednomu jídlu. Lékař navíc jedním zaškrtnutím potvrdí, že pacient nemá vylučovací kritérium: těhotenství nebo jeho plánování, opakované těžké poklesy glukózy nebo jejich nepoznávání, těžké onemocnění ledvin nebo jater, léčbu akarbózou (nízká glukóza se u ní léčí jen hroznovým cukrem), potíže s chůzí nebo pohybem, kvůli kterým nezvládne procházku po jídle, potíže se zrakem nebo pamětí, které znemožní ovládat telefon. Bez toho plán nejde vydat. Na kontrole sestra s pacientem vybere, zda začal brát jiný lék na diabetes (Ne / Ano); při Ano se to zapíše do stopy a report řekne, že zápisy po změně se hodnotí zvlášť a lékař posoudí, zda NutriFee pro pacienta dál platí. Nová verze (rozhodnutí vlastníka 11. 11. 2026, bod 12): podmínky zařazení výslovně obsahují bazál jednou denně večer a léčbu bez korekčního schématu.', detail: 'Celý návrh stojí na pevné dávce inzulinu k jídlu. Jiný lék na diabetes mění riziko nízké glukózy (například derivát sulfonylurey), aniž by o něm aplikace věděla, a pokles pod 4 by se připisoval dávce nebo jídlu; proto je kohorta jen inzulin (rozhodnutí vlastníka 4. 11. 2026, nahrazuje rozhodnutí 18. 10. 2026 „tablety nebo GLP-1 navíc nevadí“). Vylučovací kritéria jsou na obrazovce, protože v ostré aplikaci protokol studie nebude (kontrola 4, 06 B4): u těhotenství by cíle a rady byly chybné, při nepoznávání poklesů neplatí předpoklad, že pacient pokles pozná a zapíše. Pacient s flexibilním dávkováním nebo na premixu by dostával rady postavené na předpokladu, který u něj neplatí.', texts: { bezpeci: 'Když otěhotníte, když vám lékař změní druh léčby (například jiný inzulin nebo inzulinovou pumpu) nebo vám přidá jiný lék na diabetes, NutriFee pro vás přestává platit. Řekněte to lékaři.' } /* kontrola 4 (06 B4): pacient v Bezpečí; SCHEMA 84: jiný lék na diabetes */, usedBy: 'zařazení a plán, krok 1 (podmínky zařazení a vylučovací kritéria), Bezpečí (kdy NutriFee přestává platit), kontrola (jiný lék na diabetes a zdravotní stav)' }) /* 18. 10. 2026 PAD povoleny; 4. 11. 2026 (SCHEMA 84) zpět jen inzulin – jiný lék mění riziko poklesu, o kterém aplikace neví */,
    A({ id: 'C-CILE', cat: 'plan', title: 'Cíle glukózy', summary: 'Výchozí (běžné) cíle pro každého pacienta: v cíli 3,9–10,0 mmol/l, ráno nalačno do 7,2, čas v cíli alespoň 70 %, čas pod cílem méně než 4 %, HbA1c do 53 mmol/mol. Při zařazení lékař volí „běžné cíle“, nebo „mírnější cíle pro starší a křehké“: čas v cíli alespoň 50 % a čas pod cílem méně než 1 %, ostatní hodnoty stejné. Lékař cíle u pacienta může při zařazení i kontrole upravit. Ze zvolených cílů pacienta vychází i semafor času v cíli.', detail: 'Z cílů vychází „v cíli / nad cílem“ u jídel, semafor v reportu i návrhy k dávce. Hodnoty jsou návrh autora makety; lékař je u konkrétního pacienta mění v plánu. Položka nese i cíl HbA1c (výchozí 53 mmol/mol, meze 42–75): dlaždice HbA1c v souhrnu kontroly ukazuje „v cíli / nad cílem“ a bod postupu „vyrovnání celkově nedosahuje cíle“ se vyhodnotí z času v cíli i HbA1c. Mírnější sada (rozhodnutí vlastníka 30. 10. 2026, hodnoty jsou návrh autora): u starších a křehkých pacientů a při riziku nízké glukózy výchozí „čas v cíli alespoň 70 %“ spolu s větví „zvýšit“ tlačí k intenzifikaci. Semafor času v cíli čte cíle pacienta z této položky (dřív zvláštní hranice v položce Semafor, kontrola 4, C15).', params: { low: 3.9, high: 10.0, fastingHigh: 7.2, tirGoal: 70, tbrGoal: 4, hba1cGoal: 53, tirGoalMirnejsi: 50, tbrGoalMirnejsi: 1 }, labels: { low: 'dolní cíl (mmol/l)', high: 'horní cíl po jídle (mmol/l)', fastingHigh: 'ráno nalačno do (mmol/l)', tirGoal: 'čas v cíli alespoň (%)', tbrGoal: 'čas pod dolním cílem méně než (%)', hba1cGoal: 'HbA1c do (mmol/mol)', tirGoalMirnejsi: 'mírnější cíle: čas v cíli alespoň (%)', tbrGoalMirnejsi: 'mírnější cíle: čas pod dolním cílem méně než (%)' }, steps: { low: 0.1, high: 0.5, fastingHigh: 0.1, tirGoal: 5, tbrGoal: 1, hba1cGoal: 1, tirGoalMirnejsi: 5, tbrGoalMirnejsi: 1 }, usedBy: 'zařazení (krok 2: běžné nebo mírnější cíle), kontrola (dlaždice a semafor, úprava cílů), report před kontrolou, hranice na stupnici jídel' }),
    A({ id: 'R-NAVYKY', cat: 'plan', title: 'Startovní sada návyků', summary: 'Všichni pacienti začínají se stejnými čtyřmi návyky: zapisovat hlavní jídla, držet obvyklou porci, potvrzovat inzulin a dávat bazál každý večer. Lékař může návyk vyřadit nebo přidat další.', detail: 'Stejný start umožní porovnat pacienty napříč studií. Personalizace přichází až z dat na první kontrole.', usedBy: 'zařazení a plán (krok 2 a 3), Dnes (Návyky dnes)' }),
    A({ id: 'R-REAKCE', cat: 'vypocty', title: 'Vyhodnocení reakce na jídlo', summary: 'Reakci na jídlo měříme nejvyšší hodnotou glukózy (vrcholem) v prvních 120 minutách po jídle. Jídlo je v cíli, když vrchol nepřekročí horní cíl pacienta (10,0 mmol/l); stejnou míru používá Dnes, týdenní shrnutí i návrh k dávce. Vzestup (vrchol minus hodnota před jídlem) slouží jen ke shodě zápisů při učení a lékař ho vidí v podkladech. Jídlo je známé, až když se aspoň 4 započítané zápisy z posledních 6 shodují (rozdíl vzestupů do 2,5 mmol/l); první zápis je „první dojem“, druhý „zatím to vypadá“, ale jen když se shoduje. Rozmezí vrcholů je pod 8 započítanými zápisy (1–7) od nejnižší po nejvyšší hodnotu, od 8 zápisů 10.–90. percentil. Když se nový zápis od dřívějších liší o 3,5 mmol/l a víc, aplikace se jednou zeptá, co bylo jinak: stejné jídlo, jiná příloha, jiné množství, jinak připravené, nebo neobvyklý den (stres, málo spánku, alkohol). Jiná příloha nebo příprava založí samostatné jídlo; jiné množství i neobvyklý den zápis z učení vyřadí. Než se zeptá, zkusí rozdíl vysvětlit radou (s radou bývá níž). Po 6 zápisech bez shody je jídlo „nestálé“ a lékař ho vidí v podkladech.', detail: 'Započítaný zápis = úplná data ze senzoru, inzulin potvrzen podle plánu, mimo nemoc a mimo neobvyklý den, obvyklá porce, stejná dávka jako dnes. Pro „v cíli“ platí vrchol (od 21. 10. 2026; dřív u jídla vzestup ≤ 3,0 a na Dnes vrchol, pacient viděl týž zápis dvakrát jinak); vzestup zůstává mírou shody zápisů při učení, aby se vysoký start dne nepřipisoval jídlu. Shoda do 2,5 mmol/l: simulace 15. 10. 2026 ukázala, že se 3 a 3,0 projde směs dvou jídel jako známé ve 100 %. Delší okno u tučných jídel je připravené, ale vypnuté (bez údaje o úpravě ho nelze zapnout automaticky). Stejné jídlo u dvou jídel dne se slévá jen při stejné dávce, jinak se učí zvlášť a pacient vidí stav ke každému jídlu dne (25. 10. 2026). Popisuje minulost, nepředpovídá.', params: { minKnown: 4, okno_min: 120, okno_tucne_min: 0, kriterium: 'vrchol', vzestup_max: 3, minQuantile: 8, shoda_mmol: 2.5, rozchod_mmol: 3.5, maxUceni: 6 }, labels: { rozchod_mmol: 'otázka při rozchodu od (mmol/l)', shoda_mmol: 'shoda zápisů: rozdíl vzestupů do (mmol/l)', maxUceni: 'nejvýš zápisů na poznání', minKnown: 'známé od (počet započítaných zápisů)', okno_min: 'okno vrcholu po jídle (min)', okno_tucne_min: 'okno u tučných (smažených) jídel z databáze (min; 0 = vypnuto)', kriterium: 'kritérium v cíli (vrchol = horní cíl pacienta; vzestup = připraveno, vypnuto)', vzestup_max: 'při kritériu vzestup: v cíli = vzestup nejvýš (mmol/l)', minQuantile: 'percentily od (počet zápisů)' }, texts: { slotKnown: '{meal} známe', slotLearning: '{meal} učíme se {n} {z} {min}', slotSimilar: '{meal} podobné známým', slotUnstable: '{meal} pokaždé jinak', slotUnknown: '{meal} zatím neznáme', slotWhy: '{meals} máte jinou dávku, proto se učíme zvlášť.' } /* rozhodnutí vlastníka 25. 10. 2026: stav učení po jídlech dne, když má jídlo u víc jídel dne rozdílnou dávku (Vaše jídla, detail jídla, hledání v kroku 2) */, usedBy: 'karta jídla a krok 3 (stupnice „Kam se po něm glukóza dostávala“), rady, report lékaře' }),
    A({ id: 'Z-GLUKOZA', cat: 'vypocty', title: 'Hodnoty glukózy opsané z aplikace senzoru', summary: 'Aplikace není napojená na výrobce senzoru. V kroku 1 pacient klepne na celé číslo, které právě ukazuje aplikace senzoru (posuvník po celých mmol/l 4–15 s konci „pod 4“ a „nad 15“ a volba „nemám hodnotu“; do SCHEMA 84 čipy); na nejvyšší hodnotu po minulém jídle se aplikace zeptá až v kroku 1 dalšího jídla a večer u bazálu (jeden pohled do senzoru na jídlo, žádná samostatná karta po 2 hodinách). Vzestup je nejvyšší hodnota minus hodnota před jídlem. „Nemám hodnotu“ zápis uloží, ale do učení se nepočítá, dokud ho nedoplní export. Opsané hodnoty později nahradí přesný průběh z exportu.', detail: 'Rozhodnutí vlastníka 15. 10. 2026: napojení na senzor by vyžadovalo souhlas výrobce a certifikaci rozhraní; dvě opsané hodnoty stačí k učení i k radě. Míra zůstává vrchol 0–120 min (ne hodnota ve 2. hodině), aby pacient i lékař viděli totéž číslo.', params: { pripominka_min: 120 }, labels: { pripominka_min: 'okno nejvyšší hodnoty po jídle (min)' }, usedBy: 'krok 1 (hodnota teď + minulé jídlo), večer u bazálu, učení' }),
    A({ id: 'Z-IMPORT', version: 'v2' /* SCHEMA 90: nová verze ke schválení */, scope: 'provozni', cat: 'vypocty', title: 'Export z aplikace senzoru', summary: 'Během plánu pacient hodnoty ze senzoru opisuje (Z-GLUKOZA). Před kontrolou mu aplikace připomene, ať pošle do ordinace export ze senzoru; sestra ho na kontrole nahraje. Export nahrává jen sestra; pacient v aplikaci nic nenahrává (27. 10. 2026). Aplikace export převede a doplní mezery; po nahrání řekne jen „Export nahrán a převeden · doplněno N jídel a N nocí“. Soubor, který převést nejde, odmítne obecnou hláškou a nic z něj nenačte. Soubor se čte jen v zařízení, měření se přiřadí k zápisům (0–180 min po jídle) a k nocím (bazál), spočítá se čas v cíli a opsané hodnoty se nahradí přesnými. Po nahrání aplikace spočítá, u kolika jídel se opsaná nejvyšší hodnota shodovala s exportem (do 1 mmol/l) – doklad pro studii, že učení z opsaných hodnot stojí na správných číslech. Bez nahraného exportu report v části Bezpečnost výslovně řekne, že noční hodnoty chybí a noční poklesy nejde posoudit (rozhodnutí vlastníka 30. 10. 2026). Nová verze (11. 11. 2026): poklesy z exportu se k jídlu přiřazují do 4 h po jídle (pokles_min), nejvyšší hodnota zůstává do 2 h; měření v čase jídla je hodnota před jídlem, ne pokles po něm. Noc (0–6 h), ranní hodnota (6 h) a hodnota před spaním (od 21 h) jsou parametry. Export se počítá jen za období aktivního plánu: export celý z jiného období se odmítne, u částečného se použije jen část v období plánu.', detail: 'Export jsou pacientova data; nepotřebuje svolení výrobce. Jak pacient export získá a jak ho aplikace převede, je otevřený úkol ostré aplikace (rozhodnutí vlastníka 27. 10. 2026: v maketě na podobě exportu nezáleží).', params: { po_jidle_min: 180, shoda_mmol: 1, pokles_min: 240, noc_od: 0, noc_do: 6, spani_od: 21 }, labels: { po_jidle_min: 'měření po jídle do (min)', shoda_mmol: 'opsaná nejvyšší hodnota se shoduje s exportem do (mmol/l)', pokles_min: 'pokles z exportu patří k jídlu do (min po jídle)', noc_od: 'noc od (hodina dne)', noc_do: 'noc do (hodina dne; první měření v tu hodinu = ranní hodnota)', spani_od: 'hodnota před spaním od (hodina dne)' }, texts: { jineObdobi: 'Export je z jiného období než současný plán. Ze souboru jsme nic nenačetli.', castObdobi: 'Část exportu byla mimo období plánu; použili jsme jen měření z období plánu.', nociChybi: 'Noční hodnoty nejsou k dispozici – bez exportu nelze posoudit noční poklesy.', pripominka: 'Před kontrolou pošlete do ordinace export ze senzoru.', navodNadpis: 'Jak na to', navod: ['V aplikaci senzoru najděte sdílení nebo export dat.', 'Vyberte období od poslední kontroly.', 'Soubor pošlete do ordinace tak, jak jste se domluvili se sestrou.', 'Když to nepůjde, vezměte telefon na kontrolu – sestra vám pomůže.'] } /* SCHEMA 86: krátký návod obecně, bez názvů výrobců a formátů (15 odst. 6a) */ /* rozhodnutí vlastníka 30. 10. 2026 (bod 5) */, usedBy: 'Dnes a Před kontrolou (připomínka poslat export), kontrola (sestra nahraje export), čas v cíli, bazál' }),
    A({ id: 'B-HYPO', cat: 'pokyny', title: 'Nízká glukóza: sledování a opakované poklesy', summary: 'Po menší porci s podaným inzulinem nebo po vynechaném jídle s inzulinem se ukáže pravidlo k menší porci a za 60 min otázka „Klesla glukóza pod 4?“; po večeři se zeptáme také za 60 min a ráno ještě, jestli glukóza klesla v noci, protože pokles po večeři bývá i mezi 22. a 24. hodinou. U každého jídla se pacienta vedle nejvyšší hodnoty zeptáme i na pokles: „Klesla glukóza do 4 hodin po jídle pod 4 mmol/l?“ (ano/ne/nevím); u zápisu, od kterého ještě neuplynuly 4 hodiny, zní otázka „Klesla glukóza od jídla zatím pod 4 mmol/l?“. Klepne-li pacient v kroku 1 na „pod 4“, hned vidí pravidlo k nízké glukóze a v takovém zápisu se neradí vůbec – ani porce, doplněk, pořadí, ani procházka; odpověď „ano, pod 4“ nechá na Dnes kartu s tímto pravidlem, dokud ji nepotvrdí. Při 2 poklesech za 7 dní ukážeme na Dnes kartu „Glukóza vám za posledních 7 dní klesla pod 4 dvakrát“ s obecnou radou, co dělat (text níže); zavírá se „Rozumím“. Rada neříká jíst víc a neradí podle porce měnit ani vynechávat dávku. Končí větou „Když glukóza klesá pod 4 opakovaně, nečekejte na kontrolu: poraďte se s lékařem, který vám inzulin předepsal.“ (rozhodnutí vlastníka 30. 10. 2026); aplikace sama nikam nevolá, nic neposílá a lékař mezi kontrolami nic nesleduje. Karta se ukáže znovu s každým dalším poklesem v okně 7 dní. Věty, které odkazují na pravidlo k nízké glukóze nebo na pravidlo „Méně jídla než obvykle“, aplikace vynechá, když dané pravidlo v plánu není. Pokles pod 4 u jídla v období při obvyklé porci a dávce podle plánu navíc blokuje na kontrole větev „zvýšit“ u dávky k tomuto jídlu (Postup posouzení dávky); pokles po menší porci nebo s jinou dávkou je v kartě lékaře varování. Práh je pevně 4 mmol/l. Další jídlo je „na řadě“ nejdřív 3 h po posledním hlavním jídle (do té doby „další“), aby se inzulin nehromadil. V reportu je samostatná část Bezpečnost. Hlášené „pod 4“ (volba v posuvníku nebo odpověď na otázku) se v návrhu k dávce počítá jako pokles pod dolní cíl (3,9 mmol/l), protože celé číslo z čipu hodnotu pod 3,9 nevyloučí; v dlaždici „Čas pod 3,9 mmol/l“ je jako samostatný údaj „hlášené poklesy pod 4 po jídle“, ne v procentech času. Noční pokles: u snídaně je v kroku 1 nepovinný čip „V noci klesla glukóza pod 4“ (bez nové otázky a bez připomínky; pacient na senzor u snídaně stejně kouká); noční pokles se počítá do poklesů za 7 dní a lékař ho na kontrole vidí u návrhu k bazálu a v části Bezpečnost. Na noc, na kterou se ráno ptá otázka po menší nebo vynechané večeři, se čip nenabízí a pokles se nepočítá dvakrát. Nová podoba (SCHEMA 86, rozhodnutí vlastníka 5. 11. 2026, nové znění ke schválení): karta po opakovaných poklesech je v bodech „Mějte u sebe vždy cukr nebo džus.“ · „Dávku inzulinu si sami neměňte, rozhoduje o ní lékař.“ · „Když glukóza klesá pod 4 opakovaně, nečekejte na kontrolu: poraďte se s lékařem, který vám inzulin předepsal.“ a pod nimi dva řádky k rozbalení „Při poklesu: pravidlo k nízké glukóze“ a „Když sníte méně než obvykle“ s celým zněním obou pravidel; věta o opakovaných poklesech je na kartě jednou (v rozbaleném pravidle k nízké glukóze se neopakuje). Karta po zapsaném poklesu říká „Pokles jsme zapsali. Lékař ho uvidí na kontrole.“ bez počtu poklesů („1 ze 2“ zrušeno, zní jako odpočet) a s pravidlem k nízké glukóze krátce. Nová verze (rozhodnutí vlastníka 11. 11. 2026): glukóza „pod 4“ před jídlem v kroku 1 se počítá jako pokles se všemi důsledky – do karty po opakovaných poklesech, do části Bezpečnost a blokuje větev „zvýšit“ u jídla, ke kterému patří (k předchozímu hlavnímu jídlu téhož dne, u snídaně k noci a bazálu). Stejná otázka „Klesla glukóza pod 4?“ za 60 min přijde i po výrazně vyšší dávce inzulinu, než je v plánu. Do 3 h po hlavním jídle je na Dnes hlavní tlačítko „Zapsat svačinu“ a další hlavní jídlo je jen vedlejší volba. Otázka na noc po večeři přijde ráno od 5:00; zpětný zápis ji založí jen do 4 h od jídla. Nová verze (rozhodnutí vlastníka 11. 11. 2026, bod 14): jeden čas – pravidlo „Méně jídla než obvykle“ i „Vyšší dávka než v plánu“ říkají „změřte za“ tentýž počet minut, za jaký se aplikace zeptá (tento parametr; dřív měla pravidla vlastní hodnotu). Po večeři se aplikace zeptá také za 60 min, ne až ráno; ranní otázka na noční pokles zůstává a pokles se počítá jednou.', detail: 'Menší porce po podaném inzulinu je jediné místo, kde aplikace může ublížit mlčením. Aplikace dávku nemění ani neradí „sněz víc“; jen připomene pravidlo a při opakování ukáže obecnou radu. Lékař mezi kontrolami nic nesleduje; poklesy vidí na kontrole v části Bezpečnost i přímo v návrhu k dávce. Plán, který na začátku do nízké glukózy nevede, do ní může vést za měsíc (hubnutí, jiné léky, ledviny); proto rada pacientovi říká, ať při opakovaných poklesech nečeká na kontrolu (kontrola 4, 06 A1).', params: { poklesy: 2, dny: 7, pripominka_min: 60, dalsi_slot_h: 3, ranni_otazka_h: 5, zpetne_h: 4 }, labels: { poklesy: 'poklesů pod 4 pro kartu s radou', dny: 'za posledních (dní)', pripominka_min: 'otázka po menší porci nebo vyšší dávce (i po večeři) za (min); týž čas říkají pravidla „Méně jídla než obvykle“ a „Vyšší dávka než v plánu“', dalsi_slot_h: 'do tolika hodin po hlavním jídle je hlavní tlačítko „Zapsat svačinu“ a další jídlo jen vedlejší volba (h)', ranni_otazka_h: 'otázka po večeři ráno od (hodina dne)', zpetne_h: 'zpětný zápis založí otázku na pokles jen do (h od jídla)' }, texts: { otazka: 'Klesla glukóza pod 4?', opakovane: 'Při každém poklesu postupujte podle pravidla k nízké glukóze. Mějte u sebe vždy cukr nebo džus. Když sníte méně než obvykle, řiďte se pravidlem „Méně jídla než obvykle“. Dávku inzulinu si sami neměňte, rozhoduje o ní lékař. Když glukóza klesá pod 4 opakovaně, nečekejte na kontrolu: poraďte se s lékařem, který vám inzulin předepsal.', lowNow: 'Teď neradíme – řiďte se pravidlem k nízké glukóze. Zápis jídla uložte podle skutečnosti.', lowNowBez: 'Teď neradíme. Zápis jídla uložte podle skutečnosti.', nocCip: 'V noci klesla glukóza pod 4', nocCipPomoc: 'Klepněte jen tehdy, když glukóza v noci klesla pod 4 mmol/l. Počítá se do poklesů za 7 dní a lékař ho uvidí na kontrole.', zapsano: 'Pokles jsme zapsali. Lékař ho uvidí na kontrole.', opakovaneBody: ['Mějte u sebe vždy cukr nebo džus.', 'Dávku inzulinu si sami neměňte, rozhoduje o ní lékař.', 'Když glukóza klesá pod 4 opakovaně, nečekejte na kontrolu: poraďte se s lékařem, který vám inzulin předepsal.'], opakovaneHypo: 'Při poklesu: pravidlo k nízké glukóze', opakovaneMene: 'Když sníte méně než obvykle' }, version: 'v4' /* SCHEMA 91 (bod 14): po večeři i za 60 min; jeden čas s I-MENE a I-VYSSI */ /* SCHEMA 90 (rozhodnutí vlastníka 11. 11. 2026, body 2, 3 a 5): glukóza pod 4 před jídlem je pokles se všemi důsledky; sledování i po výrazně vyšší dávce; po hlavním jídle hlavní tlačítko „Zapsat svačinu“ */ /* B18 (27. 10. 2026): otázka sledování a karta po opakovaných poklesech jsou hlavní texty pro pacienta; „Teď neradíme“ je druhý text (volba pod 4). SCHEMA 74: „opakovane“ nahradilo „zavolat“ – obecná rada bez výzvy volat; nezávislá kontrola 27. 10. 2026 (A2): bez rady k porci a bez rozhodování o dávce podle porce (návrh autora, garant schvaluje) */, usedBy: 'Dnes (otázka za 60 min, karta „Glukóza vám za posledních 7 dní klesla pod 4 dvakrát“), krok 1 (otázka k minulému jídlu, volba pod 4, u snídaně čip nočního poklesu), report lékaře (Bezpečnost, návrh k bazálu), návrh pod cílem' }),
    A({ id: 'R-PODOBNOST', cat: 'vypocty', title: 'Podobné jídlo podle pacienta', summary: 'Při zápisu nového jídla může pacient nepovinně odpovědět na „Podobá se některému jídlu, které už známe?“ (jedno ze známých jídel, nebo „Nic podobného“). Do třetího vlastního zápisu aplikace ukáže jen směr podle podobného jídla, slovem a ikonou (spíš v cíli / spíš nad cílem), bez čísla; od 3 vlastních zápisů se odhad už nepoužívá. Bez potvrzení se nic neodhaduje. Nové jídlo „jako X“ převezme ze seznamu jídel i údaje X pro rady (kontrola 4, B8): má-li X bílkovinu nebo tuk, doplněk se nenabízí, a je-li X jednolité, nenabízí se pořadí; doplněk se bere ze skupiny X. Jídla z databáze se k sobě přirovnávají podle předvyplněných údajů (zdroj, úprava, forma) při aspoň 3 podobných jídlech, 6 zápisech a shodě 2 ze 3.', detail: 'Složení jídla pacient nezadává (rozhodnutí 15. 10. 2026). Podobnost tedy určuje jen on sám; aplikace nehádá z názvu.', params: { minJidel: 3, minZapisu: 6, shoda: 0.67, vaha: 2, maxNaJidlo: 3 }, labels: { minJidel: 'databázová jídla: nejméně podobných', minZapisu: 'databázová jídla: nejméně zápisů', shoda: 'databázová jídla: shoda (0–1)', vaha: 'váha odhadu (virtuální zápisy)', maxNaJidlo: 'nejvýš zápisů z jednoho jídla' }, usedBy: 'nové jídlo (otázka na podobné jídlo), karta jídla a krok 3 (směr podle podobného jídla)' }),
    A({ id: 'R-SKORE', cat: 'skore', title: 'Stupeň reakce: většinou v cíli / častěji nad cílem', summary: 'Stupně jsou dva: „většinou v cíli“, když je v cíli aspoň polovina započítaných zápisů, jinak „častěji nad cílem“ (tři stupně ze 6 zápisů rozlišit nešlo, proto od 18. 10. 2026 dva). Stupeň se ukáže od 4 započítaných zápisů a počítá se z posledních 8; změní se, jen když by platil, i kdyby jeden zápis dopadl jinak. Od 8 zápisů je stupeň „ustálený“. Vždy jde o srovnání s pacientovými vlastními jídly. Stejnou mírou aplikace pacientovi řekne jednou větou, jak si vede (SCHEMA 86, nové znění ke schválení): ze započítaných zápisů posledních 7 dní po každém jídle dne zvlášť (nejvyšší hodnota proti hornímu cíli pacienta) – „většinou v cíli“, když je v cíli aspoň polovina, jinak „častěji nad cílem“, například „Tento týden: po obědě a večeři většinou v cíli, po snídani častěji nad cílem.“ Jídlo dne s méně než 3 započítanými zápisy za 7 dní se nehodnotí; když se nedá hodnotit žádné, věta zní „Zatím málo zápisů na hodnocení – stačí zapisovat dál.“ Stav je slovem a ikonou, bez procent a známek; počty („3 z 5 zápisů v cíli“) jsou až v Podrobnostech.', detail: 'Žádné známky ani „dobré/špatné jídlo“. Štítek říká, jak často po jídle zůstane v cíli. U jídla opakovaně nad cílem nikdy zákaz ani „jezte méně“ – jen zapisovat dál, porce ne větší než obvyklá; jídlo se pasivně nenabízí mezi návrhy.', params: { mirna: 0.5, odKolika: 4, oknoZapisu: 8, ustaleneOd: 8, vedu_min: 3 } /* B06 (27. 10. 2026): parametr stredni odstraněn, stupně jsou jen dva */, labels: { mirna: 'většinou v cíli od podílu v cíli (0–1)', odKolika: 'stupeň od (počet zápisů)', oknoZapisu: 'podíl z posledních (počet zápisů)', ustaleneOd: 'ustálené od (počet zápisů)', vedu_min: 'věta „jak si vedu“: jídlo dne hodnotit od (zápisů za 7 dní)' }, texts: { vedu: 'Tento týden: {casti}.', veduV: 'po {jidla} většinou v cíli', veduNad: 'po {jidla} častěji nad cílem', veduMalo: 'Zatím málo zápisů na hodnocení – stačí zapisovat dál.', veduDetail: '{jidlo}: {k} z {n} zápisů v cíli' } /* SCHEMA 86 (rozhodnutí vlastníka 5. 11. 2026, bod 5): věta „jak si vedu“ – nové znění ke schválení */, version: 'v2', usedBy: 'karta jídla a krok 3 (stupeň reakce), Dnes a Můj plán (věta „jak si vedu“), report lékaře' }),
    A({ id: 'R-PORCE', cat: 'rady', title: 'Rada: obvyklá porce', summary: 'Před píchnutím aplikace radí vrátit se k obvyklé porci z větší i z menší. Po píchnutí a při „nevím“ radí jen z větší porce zpět k obvyklé. Nikdy neřekne „snězte víc“. U menší porce před píchnutím dodá, že když chuť k jídlu chybí často, patří to na kontrolu (dávka se nastavuje na porci, kterou pacient opravdu jí); lékař v reportu vidí, kolikrát pacient menší porci ohlásil předem.', detail: 'Dávka je klíč vyrobený na obvyklou porci. Po píchnutí inzulin působí 3–5 h; návrat z větší porce k obvyklé je bezpečný, „snězte víc“ by učilo jíst podle inzulinu.', texts: { biggerBefore: 'Dejte si obvyklou porci. Vaše dávka inzulinu je nastavená na obvyklé množství – větší porce ho přesáhne.', biggerAfter: 'Dejte si obvyklou porci. Inzulin, který už máte v těle, je nastavený na obvyklé množství; větší porce ho přesáhne.', biggerUnknown: 'Dejte si obvyklou porci. Bereme to, jako by inzulin v těle byl: je nastavený na obvyklé množství a větší porce ho přesáhne.', smaller: 'Dejte si obvyklou porci. Menší porce při stejné dávce inzulinu může vést k nízké glukóze. Když vám chuť k jídlu chybí často, řekněte to na kontrole – dávka se nastavuje na porci, kterou opravdu jíte.', certainty: 'Obvyklá porce je množství, na které lékař nastavil vaši dávku.' }, usedBy: 'před jídlem' }),
    A({ id: 'R-DOPLNEK', cat: 'rady', title: 'Rada: doplněk k jídlu', summary: 'Rada doporučí přidat k jídlu bílkovinu nebo tuk a nic z jídla neubírat. Doplněk je vždy ze seznamu povolených doplňků níže (parametr položky); který se nabídne, určuje druh jídla v seznamu jídel: ke sladkému jídlu „bílý jogurt nebo hrst ořechů“, ke slanému jídlu bez přílohy „plátek sýra nebo vejce“, k teplému hlavnímu jídlu „kousek masa nebo vejce“, k novému jídlu, o jehož složení nic nevíme, „bílý jogurt, plátek sýra nebo vejce“. U jídel ze seznamu, která bílkovinu nebo tuk už mají (maso, ryba, vejce, sýr, tvaroh, jogurt, smažené), se nenabízí. Nabízí se u jídla, po kterém je pacient častěji nad cílem (pod 50 % v cíli), nebo kde ho už zkoušel, jen před píchnutím a mimo nemoc. U jídla, kde pacient odpoví „v jídle to není“, se už nenabízí; stejně tak u jídla (k témuž jídlu dne), kde ho pacient přijal aspoň třikrát, nejvyšší hodnota je u všech těch zápisů známá a ani jednou nebyl v cíli – počítají se všechny takové zápisy, i ty, které do učení nejdou.', detail: 'Doplněk se k jídlu přidává, nikdy nic nenahrazuje – množství sacharidů zůstává. Tuk a bílkovina posouvají vrchol později, proto se rada hodnotí stejným oknem jako jídlo samo (R-REAKCE). Věty u jednotlivých jídel se nepíšou ručně: skládá je tato položka ze seznamu doplňků a z údajů jídla (rozhodnutí vlastníka 29. 10. 2026), takže pacient nikdy nedostane doplněk mimo seznam. Stažení: počítají se všechny zápisy jídla (k témuž jídlu dne), u kterých pacient doplněk přijal a je známá nejvyšší hodnota.', text: 'Přidejte k jídlu {addon}, pokud vám nevadí. Z jídla nic neubírejte.', params: { stahnout_po: 3 }, labels: { stahnout_po: 'stáhnout, když ani jeden z aspoň tolika pokusů nebyl v cíli (počet)' },
      lists: { povolene: ['bílý jogurt', 'hrst ořechů', 'plátek sýra', 'vejce', 'kousek masa'], skupiny: { sladke: ['bílý jogurt', 'hrst ořechů'], slane: ['plátek sýra', 'vejce'], teple: ['kousek masa', 'vejce'], nove: ['bílý jogurt', 'plátek sýra', 'vejce'] }, skupinyNazvy: { sladke: 'sladké jídlo (kaše, pečivo se sladkým, ovoce, dezert)', slane: 'slané jídlo bez přílohy (chléb, salát, polévka, svačina)', teple: 'teplé hlavní jídlo (s přílohou)', nove: 'nové jídlo bez údajů o složení' } } /* kontrola 3, A2 (vlastník 29. 10. 2026): seznam povolených doplňků schvaluje garant; jídla nesou jen skupinu */,
      usedBy: 'před jídlem' }),
    A({ id: 'R-PORADI', cat: 'rady', title: 'Rada: pořadí jídla', summary: 'Rada doporučí sníst nejdřív část jídla, která zpomalí vzestup, a potom zbytek jídla; množství se nemění. Část jídla rada jmenuje jen ze seznamu složek níže (parametr položky) a jen tu, kterou jídlo podle seznamu jídel opravdu obsahuje; má-li jídlo dvě, jmenuje obě („zeleninu a maso“). U jídla, které takovou část nemá, a u jednolitých jídel (kaše, polévky, smíchaná, zapečená nebo zabalená jídla) se nenabízí. U nového jídla, o jehož složení nic nevíme, zní „zeleninu nebo maso, pokud jsou v jídle“. Nabízí se u jídla, po kterém je pacient častěji nad cílem (pod 50 % v cíli), nebo kde ji už zkoušel. Když pacient odpoví „v jídle to není“, u toho jídla se už nenabízí. Po píchnutí nebo při „nevím“ s menší porcí se nenabízí žádná rada, jejíž text mluví o množství jídla (zásada 3; kontrola 2, A1).', detail: 'Věty u jednotlivých jídel se nepíšou ručně: skládá je tato položka ze seznamu složek a z údajů jídla (rozhodnutí vlastníka 29. 10. 2026), takže rada nikdy nejmenuje nic, co v jídle není.', text: 'Snězte nejdřív {first}, potom zbytek jídla.',
      lists: { slozky: { zelenina: 'zeleninu', maso: 'maso', ryba: 'rybu', sunka: 'šunku', vejce: 'vejce', syr: 'sýr', tvaroh: 'tvaroh' }, nejvys: 2, nove: 'zeleninu nebo maso, pokud jsou v jídle' } /* kontrola 3, A2 */,
      usedBy: 'před jídlem' }),
    A({ id: 'R-PROCHAZKA', cat: 'rady', title: 'Rada: procházka po jídle', summary: 'Rada doporučí asi 15 minut svižné chůze po jídle. Nabízí se u jídla, po kterém je pacient častěji nad cílem (pod 50 % v cíli), nebo kde ji už zkoušel. Nenabízí se při nemoci, při glukóze pod 4 před jídlem, po menší porci s inzulinem v těle (podaným nebo „nevím“) a ve zpětném zápisu po poklesu pod 4 u toho jídla nebo později než 60 min po jídle.', detail: 'Ve zpětném zápisu jen do 60 min od jídla (rozhodnutí vlastníka 27. 10. 2026, Q3): procházka po vrcholu ho nemůže ovlivnit, proto se později nenabízí a nic se nepočítá do srovnání rad.', text: 'Po jídle se asi {minut} minut svižně projděte.', params: { minut: 15, okno_min: 60 }, labels: { minut: 'délka procházky (min)', okno_min: 've zpětném zápisu nabízet nejdéle (min po jídle)' }, usedBy: 'před jídlem, zpětný zápis' }),
    A({ id: 'D-CISTA', cat: 'davka', title: 'Čistá data pro návrhy k dávce', summary: 'Jen jídla s obvyklou porcí, dávkou potvrzenou podle plánu a včas (pro návrh k dávce nejvýš 30 min před jídlem a 15 min po něm; pro učení jídel širší okno 45 min před a 30 min po), mimo nemoc a mimo „neobvyklý den“ (stres, málo spánku, alkohol – pacient označí jedním klepnutím), s úplnými daty, bez svačiny do 120 min po jídle. Do návrhu k dávce navíc ne zpětný zápis s odhadnutým časem, ne podání až po jídle, ne dodatečně opravený inzulin (ty jdou jen do učení). Inzulin lze opravit do 60 min po jeho potvrzení (u „píchnu za chvíli“ od pozdějšího potvrzení).', detail: 'Přesně to, co lékař při posuzování dávky vylučuje ručně. Bez toho by návrh ukazoval na dávku, přestože příčina je v porci nebo podání. Podání 15–30 min před jídlem je u prandiálního inzulinu běžný postup, proto se počítá.', params: { pred_min: 30, po_min: 15, pred_uceni_min: 45, po_uceni_min: 30, svacina_min: 120, oprava_min: 60 }, labels: { pred_min: 'inzulin nejvýš před jídlem (min)', po_min: 'inzulin nejvýš po jídle (min)', pred_uceni_min: 'pro učení: inzulin nejvýš před jídlem (min)', po_uceni_min: 'pro učení: inzulin nejvýš po jídle (min)', svacina_min: 'svačina vyřazuje do (min po jídle)', oprava_min: 'oprava inzulinu možná do (min od potvrzení)' }, usedBy: 'návrhy k dávce, učení' }),
    A({ id: 'D-PRAND', version: 'v2' /* SCHEMA 90: nová verze ke schválení */, cat: 'davka', title: 'Návrhy k prandiální dávce a radám', summary: 'Návrh se týká jednoho jídla dne (snídaně, oběd nebo večeře) a ukazuje rozpad po jednotlivých jídlech, seřazený podle počtu zápisů nad cílem. Data se berou od poslední změny dávky, nejméně za 28 dní. Návrh „nad cílem“ vznikne vždy, když je aspoň 8 čistých jídel, aspoň 2/3 z nich mají vrchol do 120 min nad cílem a medián vrcholu je o víc než 0,5 mmol/l nad horním cílem. Rady jdou první: když pacient u toho jídla dne přijal radu méně než 3× nebo rady většinou odmítal (aspoň 60 % z nejméně 5 nabídek), vznikne před návrhem k dávce ještě karta „Nejdřív rady“ a v návrhu k dávce bod postupu „Pacient rady k jídlu zkoušel“ podle dat nesedí, takže větev zní „ponechat dávku, posílit radu“; lékař přesto může zvolit jinou dávku voličem. Brána rad neplatí, když bylo nabídek rad méně než 5 (aplikace rady skoro nenabízela, například u pestré stravy). Karta říká „nabídnuto N×, přijato M×“. Když nad cílem jsou hlavně jedno nebo dvě jídla (dvě jídla s nejvíc zápisy nad cílem tvoří aspoň 2/3 zápisů nad cílem) a pacient jí ke stejnému jídlu dne i jiné jídlo aspoň 2×, které je v cíli aspoň u 90 % zápisů, bod postupu má štítek „data říkají jinak“ a větev zní „ponechat dávku, řešit jídlo“. Návrh „pod cílem“ vznikne při aspoň 2 poklesech pod dolní cíl (3,9 mmol/l) do 4 h po jídle, které zároveň tvoří aspoň 15 % jídel (z nejméně 6), nebo při jediném poklesu pod 3,0 mmol/l; nízké hodnoty se berou ze všech zápisů, nejen z čistých. Hlášené „pod 4“ (volba v posuvníku nebo odpověď pacienta) se počítá jako pokles pod dolní cíl. Podíl 15 % chrání před návrhem ze dvou poklesů za tři měsíce; pokles při obvyklé porci a dávce podle plánu přitom blokuje větev „zvýšit“ v postupu posouzení dávky, pokles po menší porci nebo s jinou dávkou je v kartě varování. Karta vždy ukazuje čas v cíli, podíl času pod cílem, HbA1c a vývoj v čase (medián vrcholu v první polovině období a v posledních 4 týdnech). U jídla dne, ke kterému návrh nevznikl, má lékař v kroku 2 řádek „N z M nad cílem · bez návrhu (práh 2/3)“ se stejným voličem dávky. Nová verze (11. 11. 2026): hranice „velmi nízké“ hodnoty (dřív pevně 3,0 mmol/l v kódu) je parametr; hlášené „pod 4“ se počítá jako pokles pod dolní cíl pacienta při jakémkoli dolním cíli.', detail: 'Rady k jídlu jdou vždy první; dávka je poslední páka. Aplikace nevymýšlí směr, jen ukáže větev schváleného postupu posouzení dávky. Rozhodnutí vlastníka 4. 11. 2026 (body 1 a 2): brána „nejdřív rady“ už není výlučný blok – u zjevné a dlouhodobé hyperglykémie by tři měsíce bez posouzení dávky byly škoda; rada odmítnutá pro nedostatek času je důvod k rozhovoru, ne k odložení dávky. Lékař dávku určuje vždy (zásada 1): větev je doporučení, ne zámek.', params: { dny: 28, minJidel: 8, podil: 0.67, radyPrve: 3, hypo: 2, hypoPodil: 0.15, hypoMin: 6, medianNad: 0.5, odmitnutiMin: 5, odmitnutiPodil: 0.6, podilDvouJidel: 0.67, velmiNizka: 3.0 }, labels: { velmiNizka: 'velmi nízká hodnota po jídle pod (mmol/l; jediný pokles stačí)', odmitnutiMin: 'nejméně nabídek rad pro bránu „nejdřív rady“ (počet)', odmitnutiPodil: 'podíl odmítnutých nabídek (0–1)', podilDvouJidel: 'nad cílem jen jedno nebo dvě jídla: od podílu zápisů nad cílem (0–1)', dny: 'okno nejméně (dní)', minJidel: 'nejméně čistých jídel (počet)', podil: 'podíl nad cílem nejméně (0–1)', radyPrve: 'bod „Pacient rady k jídlu zkoušel“: přijatých rad nejméně (počet)', hypo: 'poklesů pod dolní cíl nejméně (počet)', hypoPodil: 'podíl jídel s poklesem nejméně (0–1)', hypoMin: 'jídel pro posouzení poklesů nejméně (počet)', medianNad: 'medián vrcholu nad cílem o (mmol/l)' }, usedBy: 'kontrola, krok 2 (návrhy „Posoudit prandiální dávku“, „Nejdřív rady“, „Probrat / Vyměnit / Zachovat radu“)' }),
    A({ id: 'D-BAZAL', version: 'v3' /* SCHEMA 91 (rozhodnutí vlastníka 11. 11. 2026, bod 15): jediná noc pod velmiNizka stačí bez ohledu na minNoci */, cat: 'davka', title: 'Návrh: posoudit bazální dávku', summary: 'Posuzuje se nejméně 10 nocí za 14 dní. Když je medián ranních hodnot nad cílem a žádná noc neklesla pod cíl, vznikne návrh posoudit bazál. Když aspoň 2 noci klesly pod 3,9 nebo jedna pod 3,0, vznikne návrh; přednost před ostatními kartami má jen tehdy, když některá noc klesla pod 3,0, nebo když sestra neuvedla, že pacient jí pozdě večer a v noci (jinak je karta zařazená mezi ostatní bez přednosti). Noc, ve které pacient sám zapsal u snídaně noční pokles pod 4, se počítá jako noc pod cílem i bez exportu a karta u ní uvede, že zdrojem je zápis pacienta; u jediné hodnoty pod 3,0 karta upozorní, že může jít o artefakt senzoru. Karta u každé noci pod cílem uvede okolnosti z dat: večeři (čas, jídlo, porce), čas bazálu, hodnotu před spaním a ranní hodnotu. Obě karty k bazálu a souhrn kontroly navíc uvádějí ranní hodnoty před snídaní, které pacient za celé období opsal (medián a kolik jich bylo nad cílem nalačno): bez exportu je to jediný údaj o bazálu. Nová verze (11. 11. 2026): hranice „velmi nízké“ noci (dřív pevně 3,0 mmol/l v kódu) je parametr; glukóza pod 4 před snídaní se počítá jako noc pod cílem. Nová verze (rozhodnutí vlastníka 11. 11. 2026, bod 15): jediná noc z exportu pod hranicí velmi nízké hodnoty dá kartu k bazálu bez ohledu na počet posouzených nocí (u krátkého exportu karta řekne, kolik nocí bylo posouzeno); stejně jako u inzulinu k jídlu, kde jediný pokles pod 3,0 kartu vytvoří vždy.', detail: 'Rozhodnutí vlastníka 4. 11. 2026 (32/02 A4, B6, B9, B10): karta bazálu nesmí vést ke snížení bazálu, když ranní hodnoty jsou v cíli a noci následují po jídle pozdě večer; proto okolnosti nocí, ranní hodnoty a přednost jen bez takového vysvětlení.', params: { dny: 14, nociPod: 2, minNoci: 10, velmiNizka: 3.0 }, labels: { velmiNizka: 'velmi nízká noc pod (mmol/l; jediná noc stačí)', dny: 'okno (dní)', nociPod: 'nocí pod dolním cílem nejméně (počet)', minNoci: 'nocí s daty nejméně (počet; neplatí pro noc pod hranicí velmi nízké hodnoty)' }, usedBy: 'report' }),
    A({ id: 'D-POSTUP', version: 'v2' /* SCHEMA 90: nová verze ke schválení */, cat: 'davka', title: 'Postup posouzení dávky (větve)', summary: 'Postup říká, co s pacientem ověřit a co z výsledku plyne. Když všechny body sedí a hodnoty jsou nad cílem, větev zní „zvýšit“; když nesedí podání, pacient po jídle dojídá, jsou nad cílem jen jedno či dvě jídla, pacient rady k jídlu nezkoušel nebo byl u jídla v období pokles pod 4 při obvyklé porci a dávce podle plánu, větev zní „ponechat“ a řešit příčinu. Takový pokles pod 4 větev „zvýšit“ vždy zablokuje: když nesedí víc bodů, rozhoduje bod s poklesem, ne pořadí bodů; bez schváleného postupu se zvýšení dávky u takového jídla zapíše jako rozhodnutí proti datům. Pokles po menší porci, po vynechaném jídle nebo s jinou dávkou než v plánu větev neblokuje: karta ho vypíše jako varování („poklesy po menší porci – poučit pacienta“), protože nic neříká o dávce k obvyklé porci. Větev je doporučení, ne zámek: u každé karty k dávce (i s větví „ponechat“), u každého jídla dne bez karty a v kroku potvrzení plánu má lékař volič „jiná dávka“; změna proti větvi se zapíše jako „rozhodnuto jinak než postup“, zvýšení u jídla s blokujícím poklesem navíc jako rozhodnutí proti datům. Každý postup má větev pro každý bod; kdyby některá chyběla (např. garant ji vyřadil), aplikace ukáže „ponechat dávku“, nikdy zvýšení. Sedm postupů: bazál pod a nad cílem, inzulin k jídlu pod a nad cílem, nejdřív rady, probrat / vyměnit / zachovat radu a bezpečnostní pravidla beze změny. U inzulinu k jídlu nad cílem je bod, že se opsané nejvyšší hodnoty shodují s exportem (aspoň 80 % jídel, ke srovnání aspoň 5); jinak větev zní „ponechat, posoudit příště z exportu“; a bod, že pacient rady k jídlu zkoušel (přijal je aspoň 3× z nejméně 5 nabídek); jinak větev zní „ponechat dávku, posílit radu“. Body, které z dat ověřit nejde (technika a místo píchání, jídlo mezi jídlem a měřením, jídlo pozdě večer a v noci, nemoc a stres mimo dny, které pacient zapsal), projde s pacientem výběrem sestra ještě před lékařem; lékař vidí její odpovědi, hromadné „Vše sedí“ je nepřepíná a rozhoduje on. Jídlo je „v cíli“ (varování, že příčina může být v jídle, a bod „nad cílem nejsou jen jedno nebo dvě jídla“), když je v cíli aspoň u 90 % svých zápisů. Když bod o vyrovnání sedí jen díky HbA1c o méně než 5 mmol/mol nad cílem, „Co návrh oslabuje“ to uvede. Velikost kroku vždy volí lékař. Nová verze (rozhodnutí vlastníka 11. 11. 2026): (1) čas pod cílem nad mezí – pod dolním cílem tolik procent času, kolik je cíl pacienta, nebo pod 3,0 mmol/l víc než mez semaforu – blokuje větev „zvýšit“ u všech dávek (nový bod „Čas pod cílem je pod mezí“ u inzulinu k jídlu i u bazálu ráno nad cílem; bod se nepřepíná a větev zní „ponechat – čas pod cílem nad mezí“); (2) body, které data potvrzují (fakt z dat bodu neodporuje), jsou na kontrole předvyplněné „sedí podle dat“ a lékař řeší jen ostatní; může je změnit a stopa zapíše, že rozhodl proti datům.', detail: 'Ověřovací body i věty „zvýšit / snížit / ponechat“ jsou texty této položky. Aplikace postup jen aplikuje na data a ukáže větev; krok v jednotkách postup nikdy neobsahuje. Body jsou psané v jednom smyslu: každý je věta, která musí platit, aby šlo pokračovat. U bodu, ke kterému aplikace má data, je číslo z dat; když data bodu odporují (čas v cíli nad cílem, pokles při menší porci nebo nepotvrzené dávce, rady nezkoušené), bod má štítek „data říkají jinak“ a „Vše sedí“ ho nepřepne – lékař ho posoudí sám. Výjimkou je bod „U jídla nebyl v období pokles pod 4 při obvyklé porci a dávce podle plánu“: když aplikace v období zná u jídla aspoň 1 takový pokles (opsaný, hlášený na otázku nebo z exportu), bod podle dat nesedí, lékař ho nepřepne a karta poklesy vypíše s datem. Parametr „blokují jen poklesy při obvyklé porci a dávce podle plánu“ (výchozí ano, návrh autora; rozhodnutí vlastníka 4. 11. 2026, upřesňuje rozhodnutí 27. 10. 2026): pokles s plnou dávkou po poloviční porci před jedenácti týdny nic neříká o dávce k obvyklé porci; bezpečnost pacienta tím beze změny (pravidlo „Méně jídla než obvykle“, otázka na pokles, karta po opakovaných poklesech). U bazálu v noci pod cílem karta u každé noci uvede večeři, čas bazálu, hodnotu před spaním a ranní hodnotu; přednost před ostatními kartami má jen tehdy, když noc klesla pod 3,0 nebo sestra neuvedla jídlo pozdě večer a v noci. Nesouhlasíte-li s některou větví, zamítněte; do poznámky můžete napsat, kterou vyřadit nebo jak ji změnit (nepovinné).',
      postup: {
        bazalLow: { title: 'Bazál – noční hodnoty pod cílem', verify: ['Bazál je potvrzený ve stejnou hodinu', 'Večeře v těch nocích byly obvyklé, bez alkoholu a nočního jídla', 'Pohyb v těch dnech byl běžný, bez mimořádné zátěže'], fakta: ['bazal', 'noci', null], sestraBody: [null, 'vecer', null] /* SCHEMA 84 (32/02 A4): odpověď sestry „pozdě večer a v noci pacient nic nejí“ doteče na kartu; k bodu 2 fakt z dat (ranní hodnoty, noci) */, branches: [{ when: 'body 1–3 sedí', action: 'down', text: 'snížit bazál' }, { when: 'bod 1 nesedí', action: 'keep', text: 'ponechat, řešit čas podání' }, { when: 'bod 2 nesedí', action: 'keep', text: 'ponechat, řešit večeře' }, { when: 'bod 3 nesedí', action: 'keep', text: 'ponechat, posoudit příště po dnech s běžným pohybem' }] },
        bazalHigh: { title: 'Bazál – ranní hodnoty nad cílem', verify: ['Bazál je potvrzený ve stejnou hodinu', 'Pacient nejí pozdě večer ani v noci', 'Technika a místo píchání jsou v pořádku', 'Vyrovnání celkově nedosahuje cíle: čas v cíli pod {tirGoal} % nebo HbA1c nad cílem', 'Čas pod cílem je pod mezí: pod {low} mmol/l méně než {tbrGoal} % času a pod 3,0 mmol/l méně než {tbr3} % času'], fakta: ['bazal', null, null, 'vyrovnani', 'podCilem'], sestraBody: [null, 'vecer', 'technika', null, null], branches: [{ when: 'body 1–5 sedí', action: 'up', text: 'zvýšit bazál' }, { when: 'bod 1 nesedí', action: 'keep', text: 'ponechat, řešit podání' }, { when: 'bod 2 nesedí', action: 'keep', text: 'ponechat, řešit večeře' }, { when: 'bod 3 nesedí', action: 'keep', text: 'ponechat, řešit techniku a místo píchání' }, { when: 'bod 4 nesedí', action: 'keep', text: 'ponechat – celkově v cíli, zvažte riziko nízké glukózy' }, { when: 'bod 5 nesedí', action: 'keep', text: 'ponechat – čas pod cílem nad mezí, nejdřív řešit nízkou glukózu' }] },
        prandLow: { title: 'Inzulin k jídlu – hodnoty pod cílem', verify: ['Při poklesech byla porce obvyklá, ne menší', 'Při poklesech byla dávka potvrzená podle plánu a včas', 'Pohyb po jídle byl běžný'], fakta: ['porcePoklesy', 'davkaPoklesy', null], branches: [{ when: 'body 1–3 sedí', action: 'down', text: 'snížit dávku {meal}' }, { when: 'bod 1 nesedí', action: 'keep', text: 'ponechat, řešit porce' }, { when: 'bod 2 nesedí', action: 'keep', text: 'ponechat, řešit podání' }, { when: 'bod 3 nesedí', action: 'keep', text: 'ponechat, posoudit příště po dnech s běžným pohybem' }] },
        prandAdviceFirst: { title: 'Inzulin k jídlu – nejdřív rady', verify: ['Pacient radu může běžně plnit (má to doma, chutná mu, stihne to)', 'Pacient je ochotný ji zkoušet'], fakta: [null, 'rady'], branches: [{ when: 'oba body sedí', action: 'keep', text: 'ponechat dávku, posílit radu' }, { when: 'bod 1 nesedí', action: 'swap', text: 'vyměnit radu „{lever}“ za jinou' }, { when: 'bod 2 nesedí', action: 'keep', text: 'ponechat dávku, probrat důvody' }] },
        prandHigh: { title: 'Inzulin k jídlu – hodnoty nad cílem', verify: ['Dávky {meal} jsou potvrzené podle plánu a včas', 'Technika a místo píchání jsou v pořádku', 'Vrcholy po jídle jsou nad cílem opakovaně, ne jednorázově', 'Mezi jídlem a měřením pacient nic dalšího nejedl', 'V těch dnech pacient nebyl nemocný ani ve větším stresu', 'Vyrovnání celkově nedosahuje cíle: čas v cíli pod {tirGoal} % nebo HbA1c nad cílem', 'Nad cílem nejsou jen jedno nebo dvě jídla', 'U jídla nebyl v období pokles pod 4 při obvyklé porci a dávce podle plánu', 'Opsané nejvyšší hodnoty se shodují s exportem', 'Pacient rady k jídlu zkoušel (přijal aspoň {radyPrve}× z nejméně {odmitnutiMin} nabídek)', 'Čas pod cílem je pod mezí: pod {low} mmol/l méně než {tbrGoal} % času a pod 3,0 mmol/l méně než {tbr3} % času'], fakta: ['davky', null, 'vrcholy', 'svacina', 'nemoc', 'vyrovnani', 'jidla', 'poklesy', 'shoda', 'rady', 'podCilem'], sestraBody: [null, 'technika', null, 'jidlo', 'stres', null, null, null, null, null, null], branches: [{ when: 'všechny body sedí a hodnoty jsou nad cílem', action: 'up', text: 'zvýšit dávku {meal}' }, { when: 'bod 1 nesedí', action: 'keep', text: 'ponechat, řešit podání' }, { when: 'bod 2 nesedí', action: 'keep', text: 'ponechat, řešit techniku a místo píchání' }, { when: 'bod 3 nesedí', action: 'keep', text: 'ponechat, posoudit příště' }, { when: 'bod 4 nesedí', action: 'keep', text: 'ponechat, řešit dojídání' }, { when: 'bod 5 nesedí', action: 'keep', text: 'ponechat, vyřadit dny nemoci a posoudit příště' }, { when: 'bod 6 nesedí', action: 'keep', text: 'ponechat – celkově v cíli, zvažte riziko nízké glukózy' }, { when: 'bod 7 nesedí', action: 'keep', text: 'ponechat dávku, řešit jídlo' }, { when: 'bod 8 nesedí', action: 'keep', text: 'ponechat dávku, řešit jídlo' }, { when: 'bod 9 nesedí', action: 'keep', text: 'ponechat, posoudit příště z exportu' }, { when: 'bod 10 nesedí', action: 'keep', text: 'ponechat dávku, posílit radu' }, { when: 'bod 11 nesedí', action: 'keep', text: 'ponechat – čas pod cílem nad mezí, nejdřív řešit nízkou glukózu' }] } /* SCHEMA 90 (rozhodnutí vlastníka 11. 11. 2026, bod 4): bod 11 čas pod cílem */ /* kontrola 4 (06 B5): bod 9 shoda opsaných vrcholů s exportem */ /* A1 (nezávislá kontrola 27. 10. 2026): pokles pod 4 u jídla v období blokuje větev „zvýšit“; SCHEMA 84 (rozhodnutí 3): jen pokles při obvyklé porci a dávce podle plánu */ /* SCHEMA 84 (rozhodnutí 2): bod 10 rady zkoušené – karta k dávce vzniká vždy, brána rad je bod, ne zámek */,
        adviceReview: { title: 'Rada k jídlu – probrat, vyměnit, zachovat', verify: ['Pacient radu může běžně plnit (má to doma, chutná mu, stihne to)'], fakta: ['rada'], branches: [{ when: 'bod 1 sedí', action: 'keep', text: 'ponechat radu, zkusit znovu' }, { when: 'bod 1 nesedí', action: 'swap', text: 'vyměnit za jinou radu' }] },
        pokynyBezeZmeny: { title: 'Bezpečnostní pravidla a cíle', verify: ['Hodnoty v pravidlech i cíle glukózy pacientovi dál odpovídají'], fakta: [null], branches: [{ when: 'bod 1 sedí', action: 'keep', text: 'ponechat' }, { when: 'bod 1 nesedí', action: 'edit', text: 'upravit hodnoty pravidel a cíle' }] } /* B10 (27. 10. 2026): body a větve návrhů k radám a „Pokyny beze změny“ přesunuty z kódu (NF.POSTUP_PENDING) do registru; bod „jen jedno nebo dvě jídla“ (A11, Q4) */
      }, sestra: { technika: 'Technika a místo píchání jsou v pořádku', jidlo: 'Kromě zapsaných jídel a svačin pacient mezi jídlem a měřením (do 2 hodin po jídle) nic dalšího nejí', vecer: 'Pozdě večer a v noci pacient nic nejí', stres: 'Kromě dnů, které pacient v aplikaci označil jako nemoc nebo neobvyklý den, nebyl v období nemocný ani ve větším stresu' } /* kontrola 4, bod 7 (vlastník 30. 10. 2026): body, které nejdou ověřit z dat, projde sestra s pacientem před lékařem. B1 (závěrečné ověření 1. 11. 2026): sestra potvrzuje jen to, co data neukážou – dny nemoci a neobvyklé dny pacient zapsal sám, zapsaná jídla a svačiny vidí lékař v datech; jídlo po jídle a jídlo v noci jsou dva body (bazál, inzulin k jídlu) */, texts: { postupne: 'Měníte {n} najednou; posuďte, zda je změnit postupně.' } /* rozhodnutí vlastníka 25. 10. 2026: při dvou a více změnách dávek v kontrole; garant text posuzuje */,
      params: { poklesy_od: 1, poklesy_jen_ciste: 1, shoda_podil: 0.8, shoda_min: 5, v_cili_podil: 0.9, hba_rezerva: 5 }, labels: { v_cili_podil: 'jídlo „v cíli“ pro varování a bod „nad cílem nejsou jen jedno nebo dvě jídla“: aspoň u podílu zápisů (0–1)', hba_rezerva: '„Co návrh oslabuje“ upozorní, když bod o vyrovnání sedí jen díky HbA1c méně než (mmol/mol) nad cílem', poklesy_od: 'bod „U jídla nebyl v období pokles pod 4“ nesedí od (počet poklesů)', poklesy_jen_ciste: 'větev „zvýšit“ blokují jen poklesy při obvyklé porci a dávce podle plánu (1 = ano, 0 = každý pokles); ostatní poklesy jsou varování' /* SCHEMA 84, rozhodnutí vlastníka 4. 11. 2026 (bod 3), návrh autora */, shoda_podil: 'bod „Opsané nejvyšší hodnoty se shodují s exportem“: shoda aspoň u podílu jídel (0–1)', shoda_min: 'bod „Opsané nejvyšší hodnoty se shodují s exportem“: jídel ke srovnání nejméně (počet)' } /* A1 (nezávislá kontrola 27. 10. 2026) */, usedBy: 'kontrola: sestra před lékařem (body, které nejdou ověřit z dat), krok 2 (návrhové karty: ověřit s pacientem, postup říká), potvrzení plánu' }),
    A({ id: 'R-POKYNY', version: 'v2' /* SCHEMA 91: „osm“ pravidel (od SCHEMA 90 i Vyšší dávka než v plánu); dřív „sedm“ */, cat: 'pokyny', title: 'Bezpečnostní pravidla jsou součást plánu', summary: 'Osm bezpečnostních pravidel pro pacienta (nízká glukóza, méně jídla než obvykle, vyšší dávka než v plánu, nevím u inzulinu, nemoc zvlášť pro inzulin na noc a pro inzulin k jídlu, vysoká glukóza, kontakty) je v plánu automaticky, každé jako vlastní položka registru s výchozí hodnotou. Jsou to obecná pravidla NutriFee, stejná pro všechny pacienty a schválená garantem. Lékař je při vydání plánu nevybírá ani nepíše: podepisuje plán jako celek a hodnotu mění jen výjimečně u konkrétního pacienta. Pacient pravidlo vidí ve chvíli, kdy ho potřebuje, bez podpisu lékaře; v Bezpečí u nich čte „Tato pravidla připravil NutriFee a posoudil je lékař.“ (rozhodnutí vlastníka 30. 10. 2026).', detail: 'Co dělat při nízké glukóze nebo při nemoci si aplikace nevymýšlí; říká to pravidlo schválené garantem. Znění navrhl vývoj, schvaluje garant při vývoji, v ostré aplikaci jsou pravidla už schválená.', usedBy: 'zařazení, kontrola, Bezpečí, nemoc, krok 1 a 3 před jídlem' }),
    A({ id: 'I-HYPO', version: 'v3' /* SCHEMA 91 (pacient N5): „minut“ celým slovem */, cat: 'pokyny', title: 'Pravidlo: nízká glukóza', summary: 'Pacient uvidí: „Když glukóza klesne pod 4 mmol/l, hned vypijte asi 1,5 dl džusu nebo snězte 3–4 kostky cukru. To je léčba nízké glukózy, ne rada k jídlu. Platí to i tehdy, když se cítíte jako při nízké glukóze (třes, pocení, hlad, zmatenost) a senzor ukazuje víc. Za 15 minut glukózu změřte znovu; když se cítíte jinak, než ukazuje senzor, změřte ji glukometrem z prstu. Když je pořád pod 4 mmol/l, dejte si džus nebo cukr ještě jednou a za 15 minut změřte znovu; když je pod 4 mmol/l i potom, volejte záchrannou službu. Když je glukóza zase nad 4 mmol/l a další jídlo máte až za víc než hodinu, snězte krajíc chleba nebo jinou malou svačinu. Kdo je zmatený, nemůže polknout nebo je v bezvědomí, nesmí nic dostat do úst: okolí volá záchrannou službu. Řekněte to i svým blízkým. Když glukóza klesá pod 4 opakovaně, nečekejte na kontrolu: poraďte se s lékařem, který vám inzulin předepsal.“ Pravidlo se ukáže, když pacient v kroku 1 zvolí „pod 4“ nebo odpoví „ano, pod 4“ na otázku k minulému jídlu; v Bezpečí je vždy. Nová verze (11. 11. 2026): „za 15 minut“ celým slovem místo zkratky „min“, aby se starším pacientům lépe četlo; obsah se nemění.', detail: 'Práh je pevně 4 mmol/l, stejné číslo jako čipy, otázky a karta po opakovaných poklesech; bez voliče. Množství džusu nebo cukru, opakování po 15 min, svačina po úpravě a hranice pro záchrannou službu jsou návrh autora makety (úplné znění, garant ho jen schvaluje); znění je bez gramů sacharidů, protože pacient sacharidy nepočítá. Cukr a svačina po poklesu jsou léčba nízké glukózy, ne rada k porci (zásada 3). Pacient vidí všude hranici 4 (celé číslo z posuvníku, v Plánu „4–10 mmol/l“), lékař v reportu dolní cíl 3,9 z položky Cíle glukózy; hlášené „pod 4“ se v návrhu k dávce počítá jako pod dolním cílem. Kontrola 4 (06 B1, A1; vlastník 30. 10. 2026): pravidlo platí i podle příznaků, když senzor ukazuje víc (senzor se zpožďuje za krví), při nesouladu glukometr z prstu, a končí větou o opakovaných poklesech. Na toto pravidlo odkazují i pravidla „Méně jídla než obvykle“, „Nevím, jestli byl inzulin píchnutý“, „Nemoc: inzulin na noc“ a karta po opakovaných poklesech; se zamítnutým pravidlem aplikace tyto odkazy vynechá. Akarbóza je vylučovací kritérium (při ní cukr ani džus nepůsobí spolehlivě).', usedBy: 'krok 1 (čip pod 4), Dnes (karta po poklesu), Bezpečí' }),
    A({ id: 'I-MENE', version: 'v3' /* SCHEMA 91 (rozhodnutí vlastníka 11. 11. 2026, bod 14; klinika K13; pacient N5) */, cat: 'pokyny', title: 'Pravidlo: méně jídla než obvykle', summary: 'Pacient uvidí: „Když sníte méně než obvykle a inzulin už je píchnutý, změřte glukózu za 60 minut. Když je pod 4 mmol/l, postupujte podle pravidla k nízké glukóze. Po alkoholu a po větší námaze než obvykle (sport, práce na zahradě) může glukóza klesnout i za několik hodin, i v noci. Mějte u sebe cukr a před spaním se podívejte na senzor.“ Pravidlo se ukáže po menší porci s už píchnutým inzulinem (krok 3) a po vynechaném jídle s inzulinem (Dnes); v Bezpečí je vždy. Nová verze (rozhodnutí vlastníka 11. 11. 2026): „za 60 minut“ je týž čas jako otázka „Klesla glukóza pod 4?“ – jeden parametr (Nízká glukóza: sledování, za kolik minut se ptáme); pravidlo nemá vlastní hodnotu a lékař ji u pacienta nemění. Dřív mohl lékař pravidlu nastavit jiný čas, než za jaký se aplikace zeptá. Po večeři se aplikace zeptá také za 60 minut, ne až ráno. Zkratku „min“ nahradilo celé slovo.', detail: 'Jediná situace, kterou aplikace sama vyvolá a která může vést k nízké glukóze; aplikace nesmí říct „snězte víc“, proto ukáže pravidlo a za 60 min se zeptá (B-HYPO). Pravidlo se ukáže vždy, i když je vyhodnocení reakce nebo rada k jídlu zamítnutá nebo pacient ještě nepřevzal plán: bezpečnostní větev nezávisí na radách (kontrola 2, A2). Věta o alkoholu a námaze (kontrola 4, 06 B2) neříká jíst víc; jen kdy může glukóza klesnout opožděně. Na pravidlo „Méně jídla než obvykle“ odkazují karta po opakovaných poklesech a nová verze rady k pořadí; se zamítnutým pravidlem aplikace tyto odkazy vynechá.', params: {} /* SCHEMA 91: čas = B-HYPO.pripominka_min */, usedBy: 'krok 3 (menší porce po píchnutí), Dnes (vynechané jídlo), Bezpečí' }),
    A({ id: 'I-NEVIM', version: 'v3' /* SCHEMA 91 (N5) */, cat: 'pokyny', title: 'Pravidlo: nevím, jestli byl inzulin píchnutý', summary: 'Pacient uvidí: „Když nevíte, jestli byl inzulin už píchnutý, znovu ho nepíchejte. Změřte glukózu za 60 minut a řiďte se pravidlem k vysoké nebo nízké glukóze.“ Pravidlo se ukáže po odpovědi „Nevím“ v kroku 1 před jídlem; v Bezpečí je vždy. Když pravidlo k nízké nebo k vysoké glukóze v plánu není, aplikace z věty vynechá odkaz na to, které chybí (kontrola 4, B6). Nová verze (11. 11. 2026): „za 60 minut“ celým slovem místo zkratky „min“; obsah se nemění.', detail: 'Dvojí dávka je nebezpečnější než vynechaná; pravidlo říká nepíchat znovu a měřit.', params: { v: 60 }, labels: { v: 'změřit glukózu za (min)' }, steps: { v: 15 }, usedBy: 'krok 1 (Nevím), Bezpečí' }),
    A({ id: 'I-NEMOC-BAZAL', cat: 'pokyny', title: 'Pravidlo: nemoc, inzulin na noc (bazál)', summary: 'Pacient uvidí: „Bazál si píchejte dál ve stejný čas, i když nejíte. Pijte a měřte glukózu každé 3 h. Když je pod 4 mmol/l, řiďte se pravidlem k nízké glukóze; když klesá opakovaně, vyhledejte ještě ten den lékařskou pomoc.“ Pravidlo se ukáže nahoře na Dnes po zapnutí „Není mi dobře“, vedle pravidla k inzulinu k jídlu; v Bezpečí je vždy.', detail: 'Při nemoci se bazál píchá dál, i když pacient nejí; jeden společný text sváděl bazál vynechat (18. 10. 2026). Nemocný bez jídla s plným bazálem může klesat, proto věta o nízké glukóze (kontrola 4, 06 B3).', params: { v: 3 }, labels: { v: 'měřit glukózu každé (h)' }, steps: { v: 1 }, usedBy: 'Dnes při nemoci, Bezpečí' }),
    A({ id: 'I-NEMOC-JIDLO', version: 'v3' /* SCHEMA 91 (pacient S1) */, cat: 'pokyny', title: 'Pravidlo: nemoc, inzulin k jídlu', summary: 'Pacient uvidí: „Když jídlo vynecháte, inzulin k němu nepíchejte. Když jíte, píchněte podle plánu. Pijte často po malých doušcích. Když zvracíte a nemůžete pít, nebo je glukóza déle než 3 hodiny nad 15 mmol/l, vyhledejte ještě ten den lékařskou pomoc. Když jste zmatení nebo se vám těžce dýchá, volejte záchrannou službu.“ Pravidlo se ukáže nahoře na Dnes po zapnutí „Není mi dobře“; v Bezpečí je vždy. Nová verze (11. 11. 2026): krátká podoba na Dnes uvádí v „Co dál“ i větu, kdy vyhledat lékařskou pomoc (dřív byla jen v celém znění).', detail: 'Inzulin k jídlu se při nemoci řídí opačně než bazál: jen když pacient jí. Znění je návrh autora: pití, kdy vyhledat lékařskou pomoc a kdy záchrannou službu (kontrola 4, 06 B3); věta o tabletách na cukrovku odpadla, kohorta je jen inzulin (4. 11. 2026); k volání do ordinace aplikace nevyzývá. Nesouhlasíte-li, zamítněte; do poznámky můžete napsat, čím znění nahradit (nepovinné).', params: { v: 15 }, labels: { v: 'hranice vysoké glukózy při nemoci (mmol/l)' }, steps: { v: 0.5 }, usedBy: 'Dnes při nemoci, Bezpečí' }),
    A({ id: 'I-VYSOKA', version: 'v3' /* SCHEMA 91 (pacient S1) */, cat: 'pokyny', title: 'Pravidlo: vysoká glukóza', summary: 'Pacient uvidí: „Když je glukóza nad 15 mmol/l, vypijte sklenici vody a pijte dál po malých doušcích. Za 2 hodiny glukózu změřte znovu. Inzulin navíc si nepíchejte a dávky neměňte. Když je glukóza i potom nad 15 mmol/l a vydrží tam déle než 3 hodiny, vyhledejte ještě ten den lékařskou pomoc. Když zvracíte, jste zmatení nebo se vám těžce dýchá, volejte záchrannou službu.“ Pravidlo se ukáže hned, když pacient zvolí „nad 15“ (glukóza teď před jídlem nebo nejvyšší po jídle), a zobrazení se zapíše do stopy; u hodnoty z minulosti (nejvyšší po jídle, zpětný zápis) nad pravidlem stojí „Podívejte se, kolik ukazuje senzor teď. Když je glukóza pořád nad 15 mmol/l, řiďte se tímto pravidlem:“; v Bezpečí je vždy. Aplikace živou glukózu nesleduje a nikoho neupozorňuje; upozornění na nízkou a vysokou glukózu si pacient nastaví v aplikaci senzoru (se sestrou při zaučení). Nová verze (11. 11. 2026): krátká podoba v okamžiku události uvádí v „Co dál“ i větu, kdy vyhledat lékařskou pomoc (dřív byla jen v celém znění).', detail: 'Znění je návrh autora: pít, za 2 hodiny změřit znovu, inzulin navíc nepíchat, když je glukóza i potom nad hranicí a vydrží tam déle než 3 hodiny, ještě ten den lékařská pomoc (stejně jako pravidlo pro nemoc), při zvracení, zmatenosti nebo dušnosti záchranná služba; pohyb při vysoké glukóze neradíme a k volání do ordinace aplikace nevyzývá. Nesouhlasíte-li, zamítněte; do poznámky můžete napsat, čím znění nahradit (nepovinné).', params: { v: 15 }, texts: { minula: 'Podívejte se, kolik ukazuje senzor teď. Když je glukóza pořád nad {v}, řiďte se tímto pravidlem:' } /* kontrola 2 (B2): hodnota z minulosti */, labels: { v: 'hranice vysoké glukózy (mmol/l)' }, steps: { v: 0.5 }, usedBy: 'krok 1 (čip „nad 15“: glukóza teď i nejvyšší po jídle), Bezpečí' }),
    A({ id: 'I-VYSSI', version: 'v3' /* SCHEMA 91 (bod 14, N5): {v} = B-HYPO.pripominka_min */, cat: 'pokyny', title: 'Vyšší dávka než v plánu', summary: 'Když pacient zapíše k jídlu výrazně vyšší dávku inzulinu, než má v plánu (o 2 j. a víc), ukáže se hned toto obecné pravidlo: častěji se dívat na senzor, mít po ruce cukr a jídlo nevynechávat. Za 60 minut se aplikace zeptá „Klesla glukóza pod 4?“ (po večeři také za 60 minut a ráno ještě na noc, B-HYPO) a v takovém zápisu se nenabízí procházka. O dávce se nic neradí a aplikace k volání nevyzývá. Pravidlo je stejné pro všechny pacienty; nově navržené (rozhodnutí vlastníka 11. 11. 2026, bod 5), ke schválení. Nová verze (11. 11. 2026, bod 14): „za 60 minut“ v pravidle je týž parametr jako čas otázky (Nízká glukóza: sledování); pravidlo nemá vlastní hodnotu.', detail: 'Vyšší dávka k obvyklé porci je stejný mechanismus nízké glukózy jako menší porce s inzulinem v těle (klinická kontrola 10. 11. 2026, K6). Hranici určuje parametr, aplikace si ji nevymýšlí. Sledování a zákaz procházky platí i se zamítnutým pravidlem (bezpečnostní větev); zamítnutí vypne jen text pravidla, na jeho místě je oznámení.', params: { nad_j: 2 }, labels: { nad_j: 'výrazně vyšší dávka = o tolik jednotek nad dávkou plánu a víc (j.)' }, usedBy: 'krok 3 zápisu po „Ano, jinak“ s vyšší dávkou, Dnes (karta s pravidlem, pak otázka „Klesla glukóza pod 4?“), Bezpečí' }),
    A({ id: 'I-KONTAKT', cat: 'pokyny', title: 'Kontakty (jen informace)', summary: 'Pacient uvidí: „Zdravotní potíže: v ordinační době ordinace, mimo ni pohotovost. Bezvědomí, křeče nebo dušnost: záchranná služba.“ Je to jen přehled kontaktů v Bezpečí (karta Kontakty a zdravotní cesty v části Kam se obrátit) a v zaučení (bod „ví, kam se obrátit s technickým problémem a kam se zdravotním“); žádná karta ani rada pacienta k volání sama neposílá (rozhodnutí vlastníka 27. 10. 2026).', detail: 'Mimo kontrolu se pacient obrací na zdravotníky sám, když to sám potřebuje; aplikace nikam nevolá, nic neposílá a k volání nevyzývá.', usedBy: 'Bezpečí, zaučení' }),
    A({ id: 'Z-BODY', scope: 'provozni', cat: 'zauceni', title: 'Body zaučení', summary: 'Tři pevné body (aplikace, Bezpečí, kontakty), body, které sestra ověří ústně – „pacient ví, že před kontrolou pošle do ordinace export ze senzoru“ (nahrává ho sestra na kontrole), „pacient má v aplikaci senzoru zapnuté upozornění na nízkou glukózu“ a „pacient si se sestrou vybral časy připomínek v telefonu a ví, že připomínka nemusí přijít“ (kontrola 4, 30. 10. 2026) – a body podle návyků ve startovním plánu. Sestra zaškrtává, co pacient udělal sám.', usedBy: 'zaučení' }),
    A({ id: 'J-DATABAZE', scope: 'provozni', cat: 'jidla', title: 'Seznam jídel', summary: 'Syntetický seznam 171 běžných českých jídel a hotovek. Skutečný zdroj a licence se vyberou pro studii.', usedBy: 'před jídlem' }),
    A({ id: 'J-STITKY', scope: 'provozni', cat: 'jidla', title: 'Nové jídlo jen názvem', summary: 'Pacient napíše název (našeptávač), případně nepovinně odpoví na „Podobá se některému jídlu, které už známe?“, a hotovo. Žádné složení, úprava, velikost ani makra – učíme se z reakce těla; složení si aplikace dovodí z chování (rada, která v jídle nejde, se vypne odpovědí „v jídle to není“). U podobného názvu se aplikace ujistí „Není to totéž jídlo?“; nové jídlo zůstává samostatné, nic se neslučuje.', detail: 'Rozhodnutí vlastníka 15. 10. 2026: pro učení z reakce těla není složení třeba; předchozí builder (zdroj · úprava · talíř) zrušen jako zbytečná zátěž. Jídla z databáze mají údaje předvyplněné, pacient je nevidí.', usedBy: 'nové jídlo' }),
    A({ id: 'S-SILNA', cat: 'report', title: 'Jídla opakovaně nad cílem: jedna věta pro lékaře', summary: 'Lékař dostane na kontrole jednu větu: kolik jídel je opakovaně nad cílem, kolik zápisů nad cílem celkem a nejvýš 3 jídla s nejvíc zápisy nad cílem; ostatní jen rozbalením. Práh: aspoň 3 zápisy nad cílem a zároveň jídlo častěji nad cílem (v cíli méně než polovina zápisů, hranice položky Stupeň reakce), nebo, u jídla se dvěma zápisy, oba nad cílem a u každého z nich vzestup aspoň 6,0 mmol/l (hranice vzestupu 3,0 a k ní 3,0; kontrola 4, C8: platí pro každý zápis zvlášť, nejde o součet). Jídla jsou seřazená podle počtu zápisů nad cílem; věta jmenuje nejvýš 3 první, úplný seznam je v podkladech pod „Další“. Aplikace u těchto jídel nabízí pacientovi rady k porci, pořadí, doplňku a procházce a jídlo sama nenabízí; lékař neprobírá jídla ani jejich složení.', detail: 'Rozhodnutí vlastníka 15. 10. 2026: lékař nesmí dostat seznam dvaceti jídel k probrání. Pacientovi žádný zákaz ani „jezte méně“ (zásada 3).', params: { silnych: 3, dvaNad_mmol: 3, maxJidel: 3 }, labels: { silnych: 'práh (počet zápisů nad cílem; jídlo navíc častěji nad cílem)', dvaNad_mmol: 'nebo 2 zápisy se vzestupem nad hranici aspoň (mmol/l)', maxJidel: 'nejvýš jídel ve větě pro lékaře' }, usedBy: 'report lékaři' }),
    A({ id: 'S-SOUHRN', version: 'v2' /* SCHEMA 91 (ordinace S8) */, scope: 'provozni', cat: 'report', title: 'Věta „co se dělo“ a srovnání rad', summary: 'Šablona z pravidel (porce, potvrzení inzulinu, rady, TIR). Když pacient za období zapsal méně než 30 % hlavních jídel, dostane lékař v kroku 2 kontroly kartu „Pacient aplikaci skoro nepoužíval“ s výzvou probrat důvod a zda pokračovat (karta, ne zámek; ordinace S8). Srovnání „s radou bývalo níž“ se říká jen od 8 zápisů s radou a 8 bez ní u téže rady a při rozdílu mediánu vrcholu ≥ 1,0 mmol/l; jinak „zatím nelze říct“. Žádná generativní AI.', detail: 'Pacient si sám volí, kdy radu přijme, takže srovnání skupin není důkaz účinku. Proto neutrální znění bez slova „fungovaly“ a bez fajfky (6. 10. 2026).', params: { min_n: 8, rozdil_mmol: 1.0, malo_zapisu_pct: 30 }, labels: { malo_zapisu_pct: 'karta „Pacient aplikaci skoro nepoužíval“ pod tolika % zapsaných hlavních jídel', min_n: 'zápisů s radou i bez ní nejméně (počet)', rozdil_mmol: 'rozdíl mediánů nejméně (mmol/l)' }, usedBy: 'report' }),
    A({ id: 'S-VYSLEDEK', scope: 'provozni', cat: 'report', title: 'Karta „Jak to dopadlo“', summary: 'Když přijdou data ze senzoru, ukáže se na Dnes jedna karta: věcně nejvyšší hodnota a poděkování za čin (vyzkoušená rada, zápis). Za hodnotu glukózy nikdy nechválíme.', detail: 'Uzavírá smyčku učení: pacient vidí výsledek toho, co udělal, ve chvíli, kdy je známý. Hodnota není jeho zásluha ani vina, proto se říká věcně; díky patří činu.',
      params: { min_n: 4 }, labels: { min_n: 'věta „bez toho u vás bývá“ od (počet zápisů s radou i bez ní)' },
      texts: { okAdvice: 'Díky za pokus – {lever} jste zůstali v cíli.{base}', excluded: 'Tento zápis do hodnocení jídla nepočítáme: {why}.', highAdvice: 'Díky za pokus. Každý zápis pomáhá poznat, co vám u tohoto jídla pomáhá.', okPlain: '{done}Díky za zápis.', highPlain: '{sugg}', suggestData: 'Příště můžete zkusit {lever} – u vás to vyšlo {k} z {n} v cíli.', suggestGeneric: 'Příště můžete zkusit doplněk k jídlu nebo jiné pořadí; nabídneme vám to před jídlem.', suggestOne: 'Příště můžete zkusit {lever}; nabídneme vám to před jídlem.', noEval: 'Vyhodnocení reakce teď neběží, výsledek nehodnotíme.', baseNote: ' Bez toho u vás bývá {lo}–{hi}.', unusable: ' Do hodnocení jídla ho nepočítáme: {why}.', nodata: 'Hodnoty ze senzoru k tomuto zápisu chybí. Zápis máme.' } /* SCHEMA 86: jídlo a nejvyšší hodnotu říká hlavička karty (stav slovem a ikonou), věta je jen poděkování nebo co dál; bez „do učení“ a bez dvojitých závorek */, usedBy: 'Dnes' }),
    A({ id: 'R-DIKY', scope: 'provozni', cat: 'rady', title: 'Poděkování po uložení', summary: 'Poděkování se řídí tím, co pacient udělal: přijatá rada, návrat k obvyklé porci, zpětné doplnění, nebo běžný zápis. Nikdy se neřídí hodnotou glukózy.', detail: 'Pochvala za číslo by učila honit čísla a jíst méně, „abych byl v cíli“. Poděkování patří tomu, co pacient udělal.',
      texts: { advice: 'Díky za pokus. Až u dalšího jídla opíšete nejvyšší hodnotu, ukážeme vám, jak to dopadlo.', portion: 'Díky za návrat k obvyklé porci. Na ni je nastavená vaše dávka.', retro: 'Díky za doplnění. I zpětný zápis se počítá.', plain: 'Zapsáno. Až u dalšího jídla opíšete nejvyšší hodnotu, uvidíte, kam se glukóza dostala.' }, usedBy: 'po uložení jídla' }),
    A({ id: 'R-MILNIKY', scope: 'provozni', cat: 'rady', title: 'Milníky za snahu a návyk', summary: 'Jednorázové milníky: jídlo poznáno, rada zdomácněla, týden bez mezery, obvyklá porce 10× po sobě, všechna častá jídla známe a zpětně doplněno 5×. Žádný milník za hodnotu glukózy. Nejde do reportu lékaře.', detail: 'Chválíme čin a vytrvalost, ne číslo. Milník se ukáže jednou jako karta na Dnes, přehled je v Plánu. Žádné body ani série s trestem.',
      texts: { known: 'Jídlo <strong>{food}</strong> už známe – víme, jak na něj obvykle reagujete.' /* SCHEMA 86 (01 D3): bez počtu „zápisů se všemi údaji“ (metoda) */ /* kontrola 4 (C11): u jídla „většinou v cíli“ se rady nenabízejí */, habit: '<strong>{food}</strong> – třikrát po sobě {lever}. Rada zdomácněla.', week1: 'Celý týden zapsaný, všech {slots} jídel. Díky.', usual10: 'Deset jídel po sobě v obvyklé porci. Na ni je nastavená vaše dávka. Díky, že ji držíte.', allknown: 'Jídla, která jíte nejčastěji ({n}), už všechna známe. Teď už hlavně doplňujeme.', retro5: 'Už pět zápisů doplněných zpětně místo vynechání. Nejvíc ale pomůže zápis před jídlem.' }, usedBy: 'Dnes, Plán' }),
    A({ id: 'S-CESTA', scope: 'provozni', cat: 'report', title: 'Cesta ke kontrole', summary: 'Karta ukazuje pruh dní do kontroly, kolik častých jídel (jedených aspoň 2×) už známe, kolik jídel je tento týden zapsáno s potvrzeným inzulinem a jednu větu o tom, co se na kontrole stane. Čísla se píší jako „X z N“, ne jako procenta, aby nepůsobila jako hodnocení.', detail: 'Dlouhodobý cíl musí být vidět: aplikace se učí pacientova jídla a na kontrole z toho lékař rozhodne. Pacient nic nepočítá.',
      texts: { goal: 'Abychom poznali vaše běžná jídla a bylo jasné, co vám u nich pomáhá. Dávky řeší lékař – vy jen jíte jako obvykle a zapisujete.', visit: 'Na kontrole lékař uvidí, jak reagujete na svá jídla a co vám pomáhá, a rozhodne, jestli něco změnit. Vy nic počítat nemusíte.' }, usedBy: 'Dnes, Plán, převzetí plánu' }),
    A({ id: 'S-TYDEN', scope: 'provozni', cat: 'report', title: 'Týdenní shrnutí „Váš týden“', summary: 'Každých 7 dní od vydání plánu karta shrne, kolik jídel je zapsáno, kolik z nich v obvyklé porci, kolik zápisů šlo do učení, kterému jídlu chybí nejméně zápisů do „známe ho“, co pomohlo a případný milník. Nabídka na příští týden z vlastních dat je připravená, ale pro studii vypnutá (rada má přicházet jen před jídlem, aby se dal změřit její účinek). Jen u pacienta.', detail: 'Jediný pravidelný rytmus mezi kontrolami. Nabídka (vypnutá) vychází z toho, co pacientovi u jiného jídla pomohlo.',
      params: { nabidka: 0 }, labels: { nabidka: 'nabídka na příští týden (0 = vypnuto, 1 = zapnuto)' },
      texts: { head: 'Váš {week}. týden', meals: 'Zapsáno {meals} z {slots} hlavních jídel, {usual} z nich v obvyklé porci.', snacks: 'K tomu {snacks}.', near: 'Nejblíž k „známému“ je {food}: chybí ještě {left}.', helped: '{lever} jste zkusili {n}×.', helpedNext: 'Co z toho vyšlo, uvidíte u jídel.', suggest: 'Příští týden zkuste u jídla {food} {lever} – jinde vám to vyšlo {k} z {n}.', thanks: 'Díky za týden zapisování.' } /* SCHEMA 86: svačiny zvlášť („22 z 21“ opraveno), pochvala činu místo „0 z 7 v cíli“, bez věty „Do učení šlo…“ */, usedBy: 'Dnes' }),
    A({ id: 'S-PODPORA', scope: 'provozni', cat: 'rezim', title: 'Kam se obrátit a kontaktní formulář', summary: 'Bezpečí rozlišuje čtyři cesty. Zdravotní cesty (ordinace, mimo ordinační dobu pohotovost, při ohrožení života záchranná služba) jsou klinický obsah a jejich znění je pravidlo Kontakty (I-KONTAKT), které schvaluje garant; tato položka jen určuje, že jsou v Bezpečí vedle technických cest. Je to jen informace; k volání aplikace nevyzývá (27. 10. 2026). Když nefunguje senzor, kontaktuje podporu výrobce (kontakt je na balení nebo v aplikaci senzoru). Když nefunguje NutriFee, vyplní kontaktní formulář v aplikaci (výběr potíže a nepovinný popis). Formulář čte technická podpora, ne lékař, a obrazovka to říká.', detail: 'Aplikace nikam nevolá ani nic neposílá sama; formulář odesílá pacient. Sestra v zaučení ověří, že pacient ví, kam s čím.', usedBy: 'Bezpečí, formulář podpory, zaučení' }),
    A({ id: 'R-ZMIZELA', scope: 'provozni', cat: 'rady', title: 'Věta o zmizelé radě', summary: 'Když garant radu zamítne a pacient ji dřív u jídla přijímal, dostane jednu neutrální větu. O garantovi se nemluví.', texts: { text: 'Radu „{lever}“ teď nenabízíme. Vaše dávky se tím nemění.' }, usedBy: 'před jídlem' }),
    A({ id: 'S-SEMAFOR', cat: 'report', title: 'Semafor času v cíli (TIR)', summary: 'Zelená, když čas v cíli (TIR) dosahuje cíle pacienta a čas pod dolním cílem je pod mezí pacienta – obojí z položky Cíle glukózy (běžné cíle: aspoň 70 % a méně než 4 %; mírnější cíle: aspoň 50 % a méně než 1 %). Oranžová při čase v cíli od 50 % do cíle pacienta. Červená při čase v cíli pod 50 %, nebo když je pod dolním cílem aspoň tolik času, kolik připouští cíl pacienta, nebo pod 3,0 aspoň 1 % času. Semafor potřebuje aspoň 14 dní dat. Dlaždice kontroly „Obvyklá porce“ a „Inzulin podle plánu“ jsou v pořádku od 80 %, oranžové pod 80 % a výrazné pod 60 %; „Mimo učení“ je oranžová od 7 dní. U procent (čas v cíli, čas pod cílem, porce, inzulin) říká dlaždice „zlepšuje se“ nebo „zhoršuje se“ až od rozdílu 2 procentních bodů, jinak „beze změny“. Vývoj v čase u glukózy (karty k dávce a tabulka jídel dne v souhrnu): medián vrcholu po jídle, u bazálu medián ranních hodnot, v první polovině období a v posledních 4 týdnech; slovo „zhoršuje se“ nebo „zlepšuje se“ až od rozdílu 1,0 mmol/l, jinak „beze změny“. Dvě čísla, ne graf.', params: { smer_pb: 2, smer_mmol: 1.0, vyvoj_tydny: 4, tir_zluta: 50, tbr3_max: 1, min_dni: 14, porce_ok: 0.8, porce_varovani: 0.6, inzulin_ok: 0.8, inzulin_varovani: 0.6, mimo_dni: 7 }, labels: { smer_pb: 'slovo „zlepšuje se / zhoršuje se“ u procent až od rozdílu (procentní body)', smer_mmol: 'vývoj v čase: slovo „zhoršuje se / zlepšuje se“ u mediánu glukózy až od rozdílu (mmol/l)', vyvoj_tydny: 'vývoj v čase: druhé číslo je medián za posledních (týdnů)' /* SCHEMA 84, rozhodnutí vlastníka 4. 11. 2026 (bod 4), návrh autora */, tir_zluta: 'oranžová od času v cíli (%)', tbr3_max: 'pod 3,0 nejvýš (%)', min_dni: 'nejméně dní dat ze senzoru', porce_ok: 'dlaždice Obvyklá porce: v pořádku od podílu (0–1)', porce_varovani: 'dlaždice Obvyklá porce: oranžová od podílu (0–1)', inzulin_ok: 'dlaždice Inzulin podle plánu: v pořádku od podílu (0–1)', inzulin_varovani: 'dlaždice Inzulin podle plánu: oranžová od podílu (0–1)', mimo_dni: 'dlaždice Mimo učení: oranžová od (dní)' } /* B11 (27. 10. 2026): prahy dlaždic kontroly z kódu do registru (A14); kontrola 4 (C15, bod 8): zelená hranice a mez času pod cílem jsou cíle pacienta z C-CILE, ne druhá hodnota tady */, usedBy: 'kontrola, krok 1 (dlaždice Čas v cíli, Obvyklá porce, Inzulin podle plánu, Mimo učení)' }),
    A({ id: 'P-NEMOC', cat: 'rezim', title: 'Režim nemoci', summary: 'Nemoc označí pacient sám a sám ji také ukončí. Zápisy z nemoci se označí a do učení se nepočítají, rady k jídlu se nedávají, platí jen bezpečnostní pravidla a aplikace se každý den zeptá „Už je vám lépe?“. Když nemoc trvá déle než 3 dny (od 4. dne), ukáže se karta „Nemoc trvá už …“ s pravidlem k nemoci; delší období nemoci jsou v reportu zvlášť.', params: { dny: 3 }, labels: { dny: 'karta „Nemoc trvá už …“ po (dnech nemoci; ukáže se od dalšího dne)' }, usedBy: 'Dnes (přepínač „Není mi dobře“, karta nemoci), krok 3 (bez rad), report' }),
    A({ id: 'P-LEKAR', cat: 'rezim', title: 'Lékař mezi kontrolami nic nedělá', summary: 'Všechny akce lékaře probíhají jen s pacientem v ordinaci. Mezi kontrolami pacienta nikdo nesleduje.', usedBy: 'celá aplikace; vydání plánu („Aplikace vám mezi kontrolami nic neposílá a nic po vás nežádá“), Dnes („Vaše zápisy uvidí lékař až s vámi na kontrole“)' }),
    /* Kontrola 4 (bod 4, rozhodnutí vlastníka 30. 10. 2026): připomínky v telefonu – provozní pravidlo (časy, texty), lékař nic nenastavuje. */
    A({ id: 'S-PRIPOMINKY', version: 'v3' /* SCHEMA 91 (pacient N3, N4; bod 14) */, scope: 'provozni', cat: 'rezim', title: 'Připomínky v telefonu', summary: 'Nejvýš 4 připomínky denně jako oznámení telefonu, bez sítě: tři k hlavním jídlům a jedna k bazálu, v časech, které pacient vybere se sestrou při zaučení. Navíc jednorázová otázka „Klesla glukóza pod 4?“ za 60 min po menší porci nebo vynechaném jídle s podaným inzulinem (B-HYPO), i po večeři. Pacient může kteroukoli připomínku vypnout; lékař nic nenastavuje. Připomínka je otázka, ne pokyn k dávce, a jen otevře Dnes; aplikace se dál řídí tím, který zápis chybí. Připomínka k jídlu, které už je zapsané nebo vynechané, nepřijde. Den má tři sloty (snídaně, oběd, večeře) a čas se používá jen hrubě: prázdný slot je minulý po 10:00 (snídaně), po 15:30 (oběd) a po 21:00 (večeře); pak se Dnes místo „Chystám se jíst“ zeptá „Byla dnes snídaně?“. Pacient se vždy může opravit sám: jídlo zapíše i zpětně, nebo ho označí jako vynechané. Nová verze (rozhodnutí vlastníka 11. 11. 2026, body 1 a 11): den aplikace končí ve 4:00 – jídlo do 4:00 patří k předchozímu dni (pozdní večeře po půlnoci je večeře). Aplikace běží vždy v českém čase; při jiném pásmu telefonu ukáže na Dnes jednu větu (text níže). Verze 11. 11. 2026: v textech připomínek „zapište“ místo „zaznamenejte“ (slovník); jméno aplikace je v oznámení telefonu nutné (výjimka z hlasu „my“).', detail: 'Zapomínající pacient otevře aplikaci jednou nebo dvakrát denně; bez připomínky chybí zápisy, nejvyšší hodnoty i odpověď na otázku po menší porci (kontrola 4, 07 A1). Připomínka nemusí přijít (vypnutý nebo ztlumený telefon); pacient ze zaučení ví, že inzulin si píchá podle plánu i bez ní.', params: { max_denne: 4, snidane_do: 10, obed_do: 15.5, vecere_do: 21, den_konec: 4 }, labels: { den_konec: 'den aplikace končí v (hodina dne; jídlo dřív patří k předchozímu dni)', max_denne: 'nejvýš připomínek denně k jídlům a bazálu', snidane_do: 'snídaně je minulá od (hodina dne; 10 = 10:00)', obed_do: 'oběd je minulý od (hodina dne; 15,5 = 15:30)', vecere_do: 'večeře je minulá od (hodina dne; 21 = 21:00)' }, /* SCHEMA 87 (15 odst. 7a): denní doby slotů z registru (NF.daypartEnd) */
      texts: { pasmo: 'Na cestách se řiďte pokyny svého lékaře; zápisy jsou v českém čase.' /* SCHEMA 90, bod 11 */, breakfast: 'Chystáte se ke snídani? Otevřete NutriFee a snídani zapište.', lunch: 'Chystáte se k obědu? Otevřete NutriFee a oběd zapište.', dinner: 'Chystáte se k večeři? Otevřete NutriFee a večeři zapište.', basal: 'Je čas na inzulin na noc. Až bude píchnutý, potvrďte ho v NutriFee.', hypo: 'Klesla glukóza pod 4? Odpovězte v NutriFee.' },
      lists: { casy: { breakfast: ['6:30', '7:00', '7:30', '8:00', '8:30'], lunch: ['11:30', '12:00', '12:30', '13:00'], dinner: ['17:30', '18:00', '18:30', '19:00'], basal: ['20:00', '21:00', '22:00'] } }, usedBy: 'zaučení (sestra s pacientem vybere časy), Plán (pacient připomínky vypne nebo zapne), oznámení telefonu, Dnes (které jídlo je na řadě a které už minulo)' }),
    /* Rozhodnutí vlastníka 1. 11. 2026 (bod 5; 06 A3): jiná dávka než v plánu. Lékař je vždy jen jeden. */
    A({ id: 'S-DAVKA', version: 'v2' /* SCHEMA 91 (rozhodnutí vlastníka 11. 11. 2026, bod 13): „Jako obvykle“ */, scope: 'provozni', cat: 'plan', title: 'Dávka podle plánu a jiná dávka než v plánu', summary: 'U dávky v kroku 1 a u bazálu je původ a datum plánu. Když pacient u téhož jídla dne dvakrát po sobě zapíše jinou dávku než v plánu, ukáže se na Dnes karta „Jiná dávka než v plánu“: „Dvakrát jste zapsali jinou dávku než v plánu. Řekněte to prosím na kontrole sestře.“ Aplikace dávku nemění ani nenavrhuje. „Jako obvykle“ (rozhodnutí vlastníka 11. 11. 2026, bod 13): když pacient jedl k témuž jídlu dne posledních 3× po sobě stejné známé jídlo v obvyklé porci s dávkou podle plánu, nabídne krok 1 vedle odpovědí o inzulinu volbu „Jako obvykle“ – jedním klepnutím zapíše inzulin podle plánu (právě teď), totéž jídlo a obvyklou porci. Glukózu pacient vybírá dál posuvníkem; rady a bezpečnostní pravidla se ukazují stejně. Volba je rovnocenná ostatním odpovědím, není předvybraná.', detail: 'Pacient se v okamžiku píchání řídí číslem na displeji; když opakovaně píchá jinou dávku, plán a skutečnost se rozcházejí a lékař to má vědět na kontrole. Aplikace se neptá proč a nic neradí.', params: { po_sobe: 2, obvykle_n: 3 }, labels: { po_sobe: 'karta po tolika zápisech jiné dávky po sobě u téhož jídla dne (počet)', obvykle_n: 'volba „Jako obvykle“ po tolika stejných zápisech po sobě u téhož jídla dne (počet)' },
      texts: { puvod: 'Podle plánu z {date}: {units} j.', nadpis: 'Jiná dávka než v plánu', karta: 'Dvakrát jste zapsali jinou dávku než v plánu. Řekněte to prosím na kontrole sestře.' }, usedBy: 'krok 1 před jídlem, Dnes (bazál, karta po dvou zápisech jiné dávky)' })
  ];
  /* SCHEMA 86 (rozhodnutí vlastníka 5. 11. 2026, bod 2): krátká podoba bezpečnostních pravidel (katalog app/data/catalogs.js: prvniKrok, coDal, kratce)
     je nová verze položky ke schválení garantem – souhrn položky ji vypíše doslova, otisk znění se tím změní. */
  var cat = (NF.data && NF.data.instructions) || [];
  var fill = function (t, c) { return String(t || '').replace(/\{v\}/g, String(c.value).replace('.', ',') + (c.unit ? ' ' + c.unit : '')); };
  list.forEach(function (r) {
    var c = cat.filter(function (x) { return x.id === r.id; })[0]; if (!c || !c.kratce) return;
    r.summary += c.prvniKrok ? ' Krátká podoba (SCHEMA 86, ke schválení): v okamžiku události nejdřív velkým písmem „' + fill(c.prvniKrok, c) + '“, pod tím „Co dál“: ' + (c.coDal || []).map(function (x) { return '„' + fill(x, c) + '“'; }).join(' · ') + '; jinde jen „' + fill(c.kratce, c) + '“. Celé znění je vždy o jedno klepnutí dál („Celé pravidlo“) a v Bezpečí. Všechny věty jsou doslova ze znění výše.'
      : ' Krátká podoba (SCHEMA 86, ke schválení): „' + fill(c.kratce, c) + '“; celé znění je o jedno klepnutí dál.';
    if (r.version === 'v1') r.version = 'v2'; /* SCHEMA 91: položka s pozdější verzí (v3, v4) si ji ponechá */
  });
  return list;

};
})(typeof window !== 'undefined' ? window : globalThis);
